        'd_milestones' => 'प्रकल्पाने वचन दिलेल्या तारखा. एक चुकवला की हेल्थ पिवळे होते आणि प्रकल्प व्यवस्थापकाला कळवले जाते.',
        'd_stages' => 'काम कसे विभागले जाते: फेज (साधे), शेवटी गेट असलेले टप्पे (टप्प्याटप्प्याचे) किंवा दोन आठवड्यांचे स्प्रिंट (अ‍ॅजाइल). गोष्ट तीच, पाहण्याचा दृष्टिकोन वेगळा.',
        'd_tasks' => 'प्रत्यक्ष काम - साधी FreeITSM कार्ये, म्हणून ती कार्ये बोर्डवर आणि लोकांच्या यादीत दिसतात.',
        'd_deps' => 'हे कार्य ते संपेपर्यंत सुरू होऊ शकत नाही. त्यांमुळे टाइमलाइनला बाण मिळतात आणि क्रिटिकल पाथ काढला जातो.',
        'd_timeline' => 'गँट चार्ट: दिनदर्शिकेवर टप्पे, कार्ये आणि माइलस्टोन, क्रिटिकल पाथ आणि एकमेकांशी भिडणाऱ्या तारखांसह.',
        'd_capacity' => 'प्रत्येक कार्यासाठी अंदाजित तास, ते करणाऱ्या लोकांमध्ये वाटलेले, म्हणजे अडचण होण्यापूर्वीच कोणावर जास्त भार आहे ते दिसते.',
        'd_people' => 'प्रकल्पात कोण आहे - विश्लेषक, संपूर्ण संघ आणि लोक मॉड्यूलमधील व्यक्ती - आणि प्रत्येकाची भूमिका.',
        'd_raci' => 'प्रत्येक वितरणीय गोष्टीसाठी: ती कोण करते, कोण जबाबदार आहे, कोणाला विचारले जाते आणि कोणाला कळवले जाते.',
        'd_stakeholders' => 'हितसंबंध असलेले सर्वजण, सत्ता आणि रसानुसार मांडलेले, ते कुठे उभे आहेत आणि त्यांना कसे माहिती दिली जाते यासह.',
        'd_raid' => 'जोखमी, गृहीतके, समस्या, अवलंबित्वे, निर्णय आणि धडे, काय चुकू शकते याच्या हीट मॅपसह.',
        'd_gates' => 'टप्प्याच्या शेवटी कोणीतरी पुढे जा, अटींसह पुढे जा किंवा थांबा असे म्हणते. आधी काय खरे असले पाहिजे ते चेकलिस्ट सांगते.',
        'd_tolerances' => 'प्रकल्प बोर्डकडे परत जाण्यापूर्वी तो किती भरकटू शकतो - उशिराचे दिवस, जोखीम गुण, बजेटपेक्षा % जास्त.',
        'd_health' => 'हिरवे, पिवळे किंवा लाल, तुम्ही प्रत्येक वेळी पाहता तेव्हा योजनेवरून काढलेले: मुदत उलटलेले काम, चुकवलेले माइलस्टोन, सहनशीलता, लक्ष्य तारीख.',
        'd_budget' => 'नियोजित विरुद्ध खर्च, ओळीनुसार, तारखांसह - म्हणजे कालानुरूप पैसा आणि शेवटपर्यंतचा अंदाज दिसतो.',
        'd_earned' => 'काय नियोजित होते, पूर्ण झालेल्या कामाची किंमत किती आणि प्रत्यक्ष खर्च किती याची तुलना करते: केलेल्या कामासाठी तुम्ही बजेटपेक्षा जास्त आहात का, आणि मागे आहात का?',
        'd_change' => 'मान्य योजनेचे बेसलाइन, आणि योजना हलण्यापूर्वी मंजूर किंवा नाकारलेल्या बदल विनंत्या.',
        'd_reports' => 'हायलाइट, अपवाद, चेकपॉइंट आणि समारोप अहवाल - तुम्ही लिहिलेले किंवा प्रकल्पाच्या स्वतःच्या डेटावरून AI ने मसुदा केलेले, मंजूर केलेले, मग ईमेल केलेले.',
        'd_alerts' => 'हेल्थ बदलते, माइलस्टोन जवळ येतो, मंजुरी खूप वेळ थांबते किंवा कार्यांची मुदत उलटते तेव्हा बेल योग्य व्यक्तीला कळवते.',
        'd_portfolio' => 'सर्व प्रकल्प एकाच वेळी: कार्ड, रोडमॅप आणि प्रकल्पांमधील चार्ट, प्राधान्य किंवा तारखेनुसार क्रमाने.',
        'd_connections' => 'प्रकल्पाशी संबंधित बदल, तिकिटे, समस्या, उपकरणे, करार, CI आणि लेख - दोन्ही बाजूंनी जोडलेले.',
        'w_goal' => 'प्रकल्पाचा फॉर्म आणि त्याचा बॅनर',
        'w_case' => 'गेट टॅब',
        'w_benefits' => 'फायदे टॅब',
        'w_scope' => 'व्याप्ती टॅब',
        'w_milestones' => 'आढावा आणि टाइमलाइन',
        'w_stages' => 'योजना टॅब',
        'w_tasks' => 'योजना टॅब, आणि कार्ये',
        'w_deps' => 'टाइमलाइन - कार्यावरील लिंक बटण',
        'w_timeline' => 'टाइमलाइन टॅब',
        'w_capacity' => 'योजना टॅब (अंदाज), आणि प्रकल्पांच्या वरच्या भागातील क्षमता',
        'w_people' => 'लोक टॅब',
        'w_raci' => 'RACI टॅब',
        'w_stakeholders' => 'लोक टॅब - सदस्यावर ठेवा',
        'w_raid' => 'RAID टॅब',
        'w_gates' => 'गेट टॅब',
        'w_tolerances' => 'गेट टॅब',
        'w_health' => 'बॅनर, आढावा आणि प्रत्येक कार्ड',
        'w_budget' => 'बजेट टॅब',
        'w_earned' => 'बजेट टॅब',
        'w_change' => 'बदल नियंत्रण टॅब',
        'w_reports' => 'अहवाल टॅब, आणि आढाव्यातील ब्रीफिंग',
        'w_alerts' => 'बेल; स्मरणपत्रांसाठी प्रकल्प - सेटिंग्ज',
        'w_portfolio' => 'प्रकल्प मुख्यपृष्ठ - कार्ड, रोडमॅप, चार्ट',
        'w_connections' => 'जोडण्या टॅब, आणि प्रत्येक नोंदीचे स्वतःचे पृष्ठ',
        's1_title' => 'सुरुवात उद्दिष्टापासून होते',
        's1_text' => 'कार्यालय स्थलांतर: "पुढील तिमाहीच्या अखेरीस सर्व 40 कर्मचारी ब्रॅडफर्डमधून काम करत आहेत." बोर्डच्या मंजुरीची गरज असल्यास, व्यवसाय प्रकरण ते का योग्य आहे ते सांगते - आणि त्याने दिलेले फायदे हेच तुम्ही शेवटी मोजाल.',
        's2_title' => 'त्याचे तुकडे करा',
        's2_text' => 'चार टप्पे: सर्वेक्षण आणि रचना, नेटवर्क उभारणी, स्थलांतराचा शनिवार-रविवार, स्थिरावणे. माइलस्टोन तुम्ही वचन दिलेल्या तारखा दर्शवतात - नेटवर्क सुरू, स्थलांतराचा दिवस.',
        's3_title' => 'कामाचे नियोजन करा',
        's3_text' => 'कार्ये प्रत्येक टप्प्यात जातात. काही इतरांची वाट पाहतात - केबलिंगपूर्वी स्विच बसवता येत नाहीत - आणि ती अवलंबित्वे टाइमलाइनचे बाण काढतात आणि क्रिटिकल पाथ शोधतात.',
        's4_title' => 'कोण काय करते',
        's4_text' => 'लोक जोडा, त्यांना भूमिका द्या, आणि कार्यांचे अंदाज द्या म्हणजे क्षमता दाखवते की कोणावर ताण आहे. मोठ्या प्रकल्पात, RACI सांगते की प्रत्येक वितरणीय गोष्टीला कोण जबाबदार आहे, आणि भागधारक नकाशा सांगतो की कोणाला खूश ठेवायचे.',
        's5_title' => 'काय आत आहे ते मान्य करा',
        's5_text' => 'व्याप्ती काय दिले जाईल ते यादी करते: प्रत्येक डेस्कला पॅच करणे Must आहे; रिसेप्शनमधील फलक Could आहे. हे लवकर उघडपणे सांगितल्याने नंतरचे वाद टळतात.',
        's6_title' => 'काय चुकू शकते त्यावर लक्ष ठेवा',
        's6_text' => 'RAID नोंदीत स्विच उशिरा येण्याची जोखीम आणि इंटरनेट लाइन लांबल्याची समस्या असते. सहनशीलता किती वाईट म्हणजे खूप वाईट ते सांगते - आणि योजना तसे म्हणते तेव्हा हेल्थ आपोआप पिवळे किंवा लाल होते.',
        's7_title' => 'पैशाचा मागोवा घ्या',
        's7_text' => 'तारखांसह बजेट ओळी कालानुरूप खर्च आणि अंदाज दाखवतात. अर्न्ड व्हॅल्यू त्याची प्रत्यक्ष झालेल्या कामाशी तुलना करते.',
        's8_title' => 'गेटवर निर्णय घ्या',
        's8_text' => 'स्थलांतराच्या शनिवार-रविवारापूर्वी, गेटची चेकलिस्ट पूर्ण असली पाहिजे - वापरकर्ता चाचणी मंजूर, बॅकआउट योजना जोडलेली - मग कोणीतरी पुढे जा म्हणते.',
        's9_title' => 'योजना हलवावी लागते तेव्हा',
        's9_text' => 'कोणाला आणखी दोन बैठक खोल्यांमध्ये स्क्रीन हव्या आहेत. बदल विनंती सांगते की दिवस आणि पैशांत त्याची किंमत किती; ती मंजूर केल्याने नवीन बेसलाइन तयार होते, म्हणून योजना किती हलली हे तुम्हाला नेहमी दिसते.',
        's10_title' => 'लोकांना कळवा',
        's10_text' => 'दर महिन्याला हायलाइट अहवाल - हवे असल्यास AI ने मसुदा केलेला, तुम्ही मंजूर केलेला, भागधारकांना ईमेल केलेला. जो कोणी गोष्टी अडवून ठेवतो त्याला बेल आठवण करून देते, आणि पोर्टफोलिओ प्रत्येक प्रकल्प शेजारी शेजारी दाखवतो.',
        's11_title' => 'FreeITSM च्या बाकीच्या भागाशी जोडा',
        's11_text' => 'नवीन स्विचसाठीचा बदल, स्थलांतरामुळे येणारी तिकिटे, केबलिंग कंपनीसोबतचा करार जोडा. त्यापैकी प्रत्येक नोंद प्रकल्प आपल्या बाजूनेही दाखवते.',
        's12_title' => 'पूर्ण करा - आणि ते योग्य ठरले का ते तपासा',
        's12_text' => 'समारोप अहवालासह प्रकल्प बंद करा. फायदे मोजत राहा: काही महिन्यांनी, नेटवर्क तिकिटे खरोखर कमी झाली आहेत का? हीच खरी कसोटी.',
    ],
