        'when_raci' => 'जेव्हा अनेक लोक काम वाटून घेतात आणि कोण निर्णय घेते हे स्पष्ट नसते.',
        'when_raid' => 'जेव्हा गोष्टी चुकू शकतात - किंवा आधीच चुकल्या आहेत.',
        'when_gates' => 'जेव्हा पुढील टप्प्यापूर्वी कोणीतरी पुढे जा किंवा थांबा असे म्हणणे गरजेचे असते.',
        'when_budget' => 'जेव्हा प्रकल्प पैसे खर्च करतो आणि त्याचा हिशोब द्यावा लागतो.',
        'when_control' => 'जेव्हा योजना मान्य झाली आहे आणि तिच्यातील बदलांना मंजुरी हवी असते.',
        'when_benefits' => 'जेव्हा प्रकल्पाचे समर्थन तो काय सुधारेल यावर केले गेले होते.',
        'why_people' => '{count} लोकांकडे त्यावर कार्ये आहेत - प्रकल्पात कोण आहे आणि त्यांच्या भूमिका यादी करा.',
        'why_scope' => '{count} कार्यांसह, व्याप्ती यादी प्रत्यक्षात काय दिले जात आहे यावर लक्ष ठेवते.',
        'why_raci' => 'त्यावर {count} लोक आहेत - RACI सांगते कोण काय करते.',
        'why_raid' => '{count} कार्यांची मुदत उलटली आहे - RAID नोंद त्यामागील समस्या आणि जोखमी मागोवा घेते.',
