        'why_control' => 'लक्ष्य तारीख आधीच हलली आहे - बेसलाइन किती ते दाखवतात, आणि बदल विनंत्या पुढचे हलणे मंजूर करतात.',
        'why_benefits' => 'त्याचे व्यवसाय प्रकरण आहे - त्याने जे वचन दिले ते मोजा.',
