            'intro' => 'प्रत्येक प्रोजेक्ट एका कार्डच्या रूपात.',
            'p1' => 'प्रोजेक्ट्स पोर्टफोलिओवर उघडतो: प्रत्येक प्रोजेक्टसाठी एक कार्ड, त्याच्या मालकाने निवडलेल्या रंगात आणि आयकॉनसह. रिंग किती काम पूर्ण झाले ते दाखवते आणि तिचा रंग स्थितीनुसार असतो; खाली लक्ष्य तारीख, कोण नेतृत्व करते आणि सध्या काय चालू आहे ते दिसते.',
            'p2' => 'डावीकडील दृश्ये नेहमीच्या प्रश्नांना उत्तर देतात - काय सुरू आहे, मी कशाचे नेतृत्व करतो, कशाकडे लक्ष हवे, काय संपले आहे - आणि वरील टाइल्स या सर्वांमध्ये महत्त्वाचे काय आहे ते मोजतात. प्रोजेक्ट सुरू करण्यासाठी **नवीन** दाबा.',
            'p3' => 'टाइल्सच्या खाली एक पट्टी सुरू असलेले प्रोजेक्ट्स कसे आहेत ते दाखवते - योग्य मार्गावर, धोक्यात, मार्गावर नाही, किंवा अजून स्थिती नाही - प्रत्येकाच्या संख्येसह. **क्रमवारी** कार्डांना लक्ष्य तारीख, प्राधान्य, स्थिती किंवा नावानुसार लावते (प्रोजेक्ट्स - सेटिंग्ज - सामान्य सुरुवातीचा क्रम ठरवते), आणि **रोडमॅप** कार्डांच्या जागी दिनदर्शिकेवर प्रत्येक प्रोजेक्टसाठी एक पट्टी दाखवतो: सुरुवातीपासून लक्ष्य समाप्तीपर्यंत, पूर्ण झालेल्या कामासाठी गडद रंगात, त्याच्या पुढील माइलस्टोनसह. प्रत्येक प्रोजेक्टला एक **प्राधान्य** असते - कमी, मध्यम, जास्त किंवा गंभीर, किंवा सेटिंग्जमधील तुमचे स्वतःचे चार शब्द - जे मध्यम नसेल तेव्हा त्याच्या कार्डावर दिसते.',
            'p4' => '**चार्ट्स** (कार्ड्स आणि रोडमॅपच्या शेजारी) दृश्यातील प्रोजेक्ट्स एकत्र दाखवतात: प्रोजेक्टनुसार प्रगती, बजेट विरुद्ध प्रत्यक्ष (प्रत्येक चलनासाठी एक चार्ट, जास्त खर्च नोंदवलेला), प्रत्येक खुल्या जोखमीचा रिस्क हीट मॅप - त्यांची यादी पाहण्यासाठी एखादा चौकोन निवडा - आणि सर्व प्रोजेक्ट्समधील प्रत्येक माइलस्टोन, गाठलेला, चुकलेला किंवा येणारा. प्रत्येक चार्टला एक **टेबल** असते.',
            'p5' => '**निर्यात** दृश्यातील प्रोजेक्ट्स - तुम्ही निवडलेले दृश्य, शोध आणि क्रम लावल्यानंतर - Excel वर्कबुक किंवा CSV फाइल म्हणून डाउनलोड करते: स्थिती, प्राधान्य, आरोग्य, प्रगती, प्रोजेक्ट मॅनेजर, तारखा, कार्ये, माइलस्टोन आणि प्रत्येक प्रोजेक्टच्या स्वतःच्या चलनातील बजेट. ज्या दृश्यात एकही प्रोजेक्ट नसतो ते काहीच निर्यात करत नाही.',
        ],
        'project' => [
            'nav' => 'प्रोजेक्ट',
            'title' => 'प्रोजेक्टचे पान',
            'intro' => 'बॅनर, नंतर आढावा, योजना, टाइमलाइन, प्रोजेक्टची टूल्स, दस्तऐवज, अहवाल, कनेक्शन्स आणि इतिहास.',
            'p1' => 'बॅनर प्रोजेक्टचे नाव, त्याचे उद्दिष्ट (पूर्ण झाल्यावर काय दिसेल), त्याची स्थिती, तो कसा चालवला जातो, कोण नेतृत्व करतो, त्याच्या तारखा आणि स्थिती रिंग दाखवतो. **संपादित करा** स्थितीसह सर्व काही बदलते: प्रोजेक्ट बंद वर सेट केल्यास, कोणीही प्रत्यक्ष समाप्ती तारीख दिली नसेल तर आजची तारीख भरली जाते.',
            'p2' => 'आढावा आकडे एकत्र आणतो, **कालानुसार प्रगती** (बर्नअप: योजनेतील प्रत्येक कार्य विरुद्ध पूर्ण झालेली, दिवसानुसार किंवा आठवड्यानुसार, लक्ष्य समाप्ती चिन्हांकित - फक्त तेवढे पाहण्यासाठी फेज निवडा, किंवा कार्यांऐवजी अंदाजित तास मोजा), आता काय चालू आहे, पुढे काय देय आहे आणि अलीकडील बदल. योजना आणि टाइमलाइननंतर प्रोजेक्ट वापरत असलेल्या प्रत्येक टूलसाठी एक टॅब येतो - लोक, व्याप्ती, RACI, RAID, गेट्स, बजेट, बदल नियंत्रण आणि लाभ, खाली वर्णन केलेले - नंतर **दस्तऐवज** (योजना, डिझाइन, मंजुरी पत्रे: अपलोड केलेली फाइल किंवा ती जिथे आहे तिथली लिंक), अहवाल आणि कनेक्शन्स. सर्व टूल्स सुरू असताना टॅब बार बाजूला स्क्रोल होतो. इतिहास काय बदलले आणि कोणी बदलले ते सर्व दाखवतो.',
            'p3' => '**कालानुसार प्रगती** (बर्नअप, किंवा **बर्नडाउन** - आदर्श रेषेच्या तुलनेत शेवटपर्यंत काय उरले आहे) खाली आढाव्यात **कार्य स्थिती** आहे (प्रत्येक टप्प्यासाठी एक पट्टी: तुमच्या कार्य स्थितींपैकी प्रत्येकात किती कार्ये आहेत, किती उशिरा आहेत किंवा दुसऱ्या कार्याची वाट पाहत आहेत), **टप्प्यानुसार प्रगती**, आणि **कालानुसार प्रवाह** - कमुलेटिव्ह फ्लो डायग्राम: प्रत्येक स्थितीतील कार्ये, दिवसानुसार. सतत रुंद होणारा पट्टा म्हणजे तिथे काम साचत आहे. स्थिती 3.3.0 पासून दिवसातून एकदा नोंदवल्या जातात; त्याआधी फक्त कार्ये कधी तयार झाली आणि पूर्ण झाली तेवढेच माहीत असते, ते राखाडी रंगात दाखवले आहे.',
            'p4' => 'चार्ट्सच्या वर, आढावा कोणाला काहीतरी करायचे आहे ते सांगतो, प्रत्येक फक्त लागू असेल तेव्हा: चुकलेला माइलस्टोन, तारीख उलटून गेलेले डिपेंडन्सी किंवा निर्णय, देय असलेली लाभ पुनरावलोकने, निर्णयाची वाट पाहणाऱ्या बदल विनंत्या आणि RAID लॉगवर एस्कलेट केलेले काहीही - प्रत्येकासह **सर्व पहा**. नंतर प्रस्तावित प्रोजेक्टवरील **प्रस्ताव** पॅनेल (प्रतीक्षेत असताना मंजूर करा आणि नाकारा), **टूलबॉक्स** (टूल्स पहा) आणि AI **ब्रीफिंग**.',
        ],
        'plan' => [
            'nav' => 'योजना',
            'title' => 'योजना तयार करणे',
            'intro' => 'आधी फेज, नंतर कार्ये.',
            'p1' => 'योजना टॅब प्रत्येक फेज (किंवा टप्पा, किंवा स्प्रिंट) कार्यांची एक लेन म्हणून दाखवतो, त्याच्या तारखा, स्थिती आणि त्यातील किती कार्ये पूर्ण झाली आहेत यासह. अजून कोणत्याही फेजमध्ये नसलेली कार्ये तळाशी असतात.',
            'p2' => 'लेनच्या खालील बॉक्समध्ये टाइप करून कार्य जोडा - हवे असल्यास ते कोण करेल आणि केव्हा देय आहे ते निवडा. कार्य हलवण्यासाठी ते दुसऱ्या लेनवर ड्रॅग करा, किंवा लेनचा क्रम लावण्यासाठी त्याच लेनमध्ये वर-खाली ड्रॅग करा - ते कुठे पडेल हे एक रेषा दाखवते. कीबोर्डवरून, कार्याच्या हँडलवर फोकस करा आणि वर किंवा खाली अ‍ॅरो दाबा; फोनवर, प्रत्येक कार्यावरील हलवा बटणात वर आणि खाली आहे. कार्य कार्ये बोर्डवर उघडण्यासाठी त्यावर क्लिक करा, तिथे ते इतर कोणत्याही कार्याप्रमाणे संपादित केले जाते.',
            'p3' => 'फेजवर काम सुरू होताना त्यावर **सुरू करा** दाबा आणि ते संपल्यावर **पूर्ण करा**. कार्याच्या ओळीच्या शेवटी असलेला क्रॉस ते प्रोजेक्टमधून काढतो; कार्य स्वतः राहते.',
            'p4' => 'माइलस्टोन म्हणजे प्रोजेक्ट ज्या तारखांचे वचन देतो - स्थलांतराचा दिवस, गो-लाइव्ह, बोर्डची मंजुरी. एखादा जोडण्यासाठी योजना टॅबवर **माइलस्टोन** दाबा, फेजमध्ये किंवा संपूर्ण प्रोजेक्टसाठी. प्रत्येक फेज त्याचे माइलस्टोन हिऱ्यांच्या रूपात दाखवतो; ते घडल्यावर **गाठला** वर टिक करा. गाठल्याशिवाय तारीख उलटून गेलेला माइलस्टोन चुकलेला मानला जातो आणि प्रोजेक्टला पिवळे करतो.',
            'step1' => 'पोर्टफोलिओवर **नवीन** दाबा, प्रोजेक्टला नाव आणि उद्दिष्ट द्या, आणि तुम्ही तो कसा चालवता ते निवडा.',
            'step2' => 'योजना टॅबवर, कामाचे जे फेज पडतात ते जोडा.',
            'step3' => 'प्रत्येक फेजखाली कार्ये जोडा, ती कोण करतो आणि केव्हा ते नमूद करून.',
            'step4' => 'पहिला फेज सुरू करा. तेव्हापासून रिंग आणि स्थिती स्वतःच अद्ययावत राहतात.',
        ],
        'timeline' => [
            'nav' => 'टाइमलाइन',
            'title' => 'टाइमलाइन',
            'intro' => 'संपूर्ण योजना दिनदर्शिकेवर.',
            'p1' => 'टाइमलाइन टॅब योजनेला गँट चार्ट म्हणून काढतो: प्रत्येक फेज, टप्पा किंवा स्प्रिंट त्याच्या तारखांवर पसरलेला पट्टा असतो, त्याची कार्ये सुरुवातीपासून देय तारखेपर्यंतच्या पट्ट्या असतात, आणि माइलस्टोन हिरे असतात - गाठला की हिरवा, चुकला की लाल. एक रेषा आजचा दिवस आणि दुसरी लक्ष्य समाप्ती दाखवते.',
            'p2' => 'माउसने, कार्य किंवा फेज हलवण्यासाठी पट्टा ड्रॅग करा, किंवा तो कधी सुरू होतो किंवा संपतो ते बदलण्यासाठी कोणतेही टोक ड्रॅग करा; माइलस्टोन हलवण्यासाठी हिरा ड्रॅग करा. प्रत्येक बदल लगेच जतन होतो आणि हाताने संपादित करताना लागू असलेल्या नियमांतूनच जातो, त्यामुळे कार्ये बोर्ड, दिनदर्शिका आणि स्थिती त्याप्रमाणे बदलतात. त्याऐवजी उघडण्यासाठी पट्ट्यावर क्लिक करा. तारखा नसलेली कार्ये काढली जात नाहीत; टॅब किती आहेत ते सांगतो.',
            'p3' => 'झूम करण्यासाठी **दिवस**, **आठवडे** किंवा **महिने** निवडा. फोनवर चार्ट बाजूला स्क्रोल होतो; गोष्टी हलवण्यासाठी त्यांना टॅप करून तारखा बदला.',
            'p4' => '**डिपेंडन्सी.** कार्याच्या ओळीवरील लिंक बटण ते कशाची वाट पाहते ते सांगते: दुसरे कार्य पूर्ण होईपर्यंत एखादे कार्य सुरू होऊ शकत नाही, ऐच्छिक काही दिवसांच्या अंतरासह. चार्टवर बाण त्यांना जोडतात - योजनेत विसंगती असेल तेव्हा लाल आणि तुटक (दुसरे पूर्ण होण्याआधीच ते सुरू होते). **क्रिटिकल पाथ** ज्या कार्यांना मोकळीक नाही ती निवडतो - ते कोणत्याही दिवशी उशिरा झाले तर समाप्ती उशिरा होते - आणि बाकीची फिकट करतो. लूप नाकारला जातो. योजनेवर, कार्य ज्याची वाट पाहते ते अपूर्ण असताना कार्य **1 ची वाट पाहत आहे** दाखवते, आणि त्याच्या तारखा जुळू शकत नाहीत तेव्हा **विसंगती**.',
        ],
        'capacity' => [
            'nav' => 'क्षमता',
            'title' => 'अंदाज आणि क्षमता',
            'intro' => 'पुढील आठवड्यांमध्ये कोणाकडे जागा आहे आणि कोणावर जास्त भार आहे.',
            'p1' => 'कार्याला **अंदाज** द्या - त्याला किती तास लागावेत - त्याच्या योजना ओळीवरील बॉक्समध्ये, किंवा कार्ये बोर्डवरील कार्य विंडोमध्ये. प्रत्येक लेन आणि आढावा मग अंदाजित विरुद्ध नोंदवलेला वेळ दाखवतात, आणि अंदाजापेक्षा जास्त वेळ नोंदवला गेला की ओळ लाल होते.',
            'p2' => 'प्रोजेक्ट्सच्या वरील **क्षमता** पानावर प्रोजेक्ट काम असलेल्या प्रत्येक व्यक्तीसाठी एक ओळ आणि प्रत्येक आठवड्यासाठी एक स्तंभ असतो. आठवड्याचा भार म्हणजे त्यांचे उरलेले प्रोजेक्ट काम - प्रत्येक कार्याचा अंदाज वजा आधीच नोंदवलेला वेळ, त्याच्या सुरुवातीपासून (किंवा आजपासून) देय तारखेपर्यंतच्या कामाच्या दिवसांत विभागलेला - अधिक सर्व्हिस-डेस्क रोटावरील त्यांच्या शिफ्ट्स, ते आठवड्यात काम करत असलेल्या तासांच्या तुलनेत. हिरवा म्हणजे जागा आहे, पिवळा म्हणजे ताण, लाल म्हणजे जास्त भार. त्यामागील कार्ये पाहण्यासाठी ओळ उघडा.',
            'p3' => 'आठवड्यांच्या शेजारी प्रत्येक व्यक्तीचे किती सुरू असलेले प्रोजेक्ट्स खुल्या कामासह आहेत (तीन किंवा अधिक असल्यास चिन्हांकित), त्यांची खुली तिकिटे, आणि देय तारीख नसलेले काम दिसते. अंदाज नसलेली कार्ये मोजली जातात पण बेरजेत धरली जात नाहीत, म्हणून पान किती आहेत ते सांगते - अज्ञात काम हा धोका आहे, काहीच नाही असे नाही. **प्रोजेक्ट्स - सेटिंग्ज - आरोग्य** आठवड्यातील तास (37.5), आठवडा केव्हा पिवळा होतो (85%), अनेक म्हणजे किती प्रोजेक्ट्स, कोणते दिवस कामाचे दिवस आहेत, आणि रोटा शिफ्ट्स मोजल्या जातात का (फक्त ऑन-कॉल रोटासाठी ते बंद करा) ते ठरवते.',
        ],
        'methods' => [
            'nav' => 'कामाच्या पद्धती',
            'title' => 'साधा, टप्प्यांचा आणि अ‍ॅजाइल',
            'intro' => 'एक प्रोजेक्ट, पाहण्याच्या तीन पद्धती.',
            'p1' => 'तुम्ही प्रोजेक्ट कसा चालवता यावरून त्याच्या टाइमबॉक्सना काय म्हणतात आणि ते कसे वागतात ते ठरते. आतून प्रत्येक प्रोजेक्ट एकाच प्रकारे बनवलेला असतो, म्हणूनच मत बदलणे सुरक्षित असते.',
            'p2' => 'मधेच पद्धत बदलल्याने काहीही गमावले जात नाही. पूर्ण झालेले फेज ज्या नावाखाली चालवले गेले ते नाव राखतात, खुले फेज नव्या पद्धतीचे नाव घेतात, आणि बदल प्रोजेक्टच्या इतिहासात नोंदवला जातो. जर नवीन पद्धतीत एका वेळी फक्त एकच टाइमबॉक्स सुरू असू शकत असेल, तर सर्वात आधीचा सुरू राहतो आणि बाकीचे पुन्हा नियोजित होतात.',
            'simple_d' => 'फेज आणि कार्ये. कितीही फेज एकाच वेळी सुरू असू शकतात.',
            'staged_d' => 'पुढचा सुरू करण्यापूर्वी एका वेळी एक पूर्ण करायचे टप्पे, PRINCE2 पद्धतीने - बोर्डला अहवाल देणाऱ्या प्रोजेक्ट्ससाठी.',
            'agile_d' => 'स्प्रिंट्स, एका वेळी एक - शिकत जाताना बदलणाऱ्या कामासाठी.',
        ],
        'tools' => [
            'nav' => 'टूल्स',
            'title' => 'प्रोजेक्टची टूल्स आणि त्यांना जुळवून घेणे',
            'intro' => 'चालवण्याची प्रत्येक पद्धत स्वतःचा संच सुरू करते.',
            'p1' => 'प्रोजेक्ट आठ टूल्स वापरू शकतो, प्रत्येक स्वतःच्या टॅबवर: लोक, व्याप्ती, RACI, RAID, गेट्स, बजेट, बदल नियंत्रण आणि लाभ. तो कसा चालवला जातो यावरून सुरुवातीला कोणती सुरू असतील ते ठरते:',
            'p2' => 'प्रोजेक्टला जुळवून घेण्यासाठी, त्याला **संपादित करा** आणि **टूल्स** खालील टूल्सवर टिक करा किंवा टिक काढा (हा विभाग संपादन करताना दिसतो, तयार करताना नाही). टूल बंद केल्याने फक्त त्याचा टॅब लपतो: त्यातील काहीही हटवले जात नाही, आणि पुन्हा सुरू केल्यावर सर्व काही परत येते. त्याच डायलॉगमध्ये प्रोजेक्ट चालवण्याची पद्धत बदलल्यास टूल्स नव्या पद्धतीच्या स्वतःच्या संचावर परत जातात.',
            'p3' => 'आढाव्यावरील **टूलबॉक्स** प्रोजेक्ट अजून वापरत नसलेली टूल्स यादीत दाखवतो - प्रत्येक कशासाठी आहे आणि ते केव्हा हवे - जेणेकरून साधा प्रोजेक्ट गरजेनुसार आपली टूल्स वाढवू शकतो. प्रोजेक्ट स्वतः सुचवतो ती आधी येतात, **सुचवलेले** म्हणून चिन्हांकित, कारणासह: तीन किंवा अधिक टप्पे गेट्स सुचवतात, आधीच पुढे गेलेली लक्ष्य तारीख बदल नियंत्रण सुचवते, उशिरा झालेले कार्य RAID सुचवते. **जोडा** संपादित करा प्रमाणेच टूल सुरू करते (RACI जोडल्यास लोक आणि व्याप्तीही जोडली जातात, कारण मॅट्रिक्स त्यांपासून बनते). **लपवा** ते त्या प्रोजेक्टसाठी तुमच्या ब्राउझरमध्ये लपवते. फक्त प्रोजेक्ट बदलू शकणाऱ्या व्यक्तींनाच ते दिसते, आणि प्रोजेक्ट बंद झाल्यावर नाही. **प्रोजेक्ट्स - सेटिंग्ज - सामान्य - आढाव्यावरील टूलबॉक्स** ते सर्वांसाठी बंद करते.',
        ],
        'people' => [
            'nav' => 'लोक',
            'title' => 'लोक आणि भूमिका',
            'intro' => 'प्रोजेक्टवर कोण आहे आणि प्रत्येकाची भूमिका काय.',
            'p2' => 'भूमिका **प्रोजेक्ट्स - सेटिंग्ज - भूमिका** मधून येतात, जी PRINCE2 पद्धतीच्या भूमिकांनी (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance आणि Project Support) तसेच Team member आणि Stakeholder यांनी सुरू होते.',
            'p4' => '**कोण पाहू शकते** (प्रोजेक्टच्या फॉर्मवर): **प्रोजेक्ट्स असलेले सर्वजण**, किंवा **फक्त सदस्य** - फक्त त्याचा प्रोजेक्ट मॅनेजर, तो ज्याने तयार केला तो, त्याचे सदस्य (थेट किंवा संघाद्वारे) आणि प्रोजेक्ट्स व्यवस्थापित करणारे लोक. HR, सुरक्षा किंवा गोपनीय कामासाठी. इतर सर्वांसाठी फक्त-सदस्य प्रोजेक्ट अस्तित्वातच नसतो: पोर्टफोलिओमध्ये, शोधात, लोक मध्ये, Watchtower, Warbot किंवा API मध्ये नाही, आणि त्याच्या तारखा शेअर केलेल्या दिनदर्शिकेवर येत नाहीत. क्षमता अजूनही त्याची कार्ये "फक्त-सदस्य प्रोजेक्ट" म्हणून मोजते. ज्याला तुम्ही मंजुरी किंवा सही करायला सांगता ती व्यक्ती उघडण्यासाठी सदस्य असली पाहिजे. नवीन प्रोजेक्ट्स प्रोजेक्ट्स -> सेटिंग्ज -> सामान्य सांगते त्याप्रमाणे सुरू होतात.',
            'p5' => '**कोणाला कळवायचे?** - भागधारक नकाशा. सदस्यावरील **ठेवा** त्यांचे **सामर्थ्य** (ते प्रोजेक्टवर किती परिणाम करू शकतात) आणि **रस** (प्रोजेक्टचा त्यांच्यावर किती परिणाम होतो), 1 ते 5, ते कुठे उभे आहेत (champion, supporter, neutral, sceptic किंवा blocker) आणि त्यांना कसे कळवले जाते ते ठरवते. नकाशा प्रत्येकाला एका चतुर्थांशात ठेवतो - जवळून सांभाळा, समाधानी ठेवा, माहिती द्या, लक्ष ठेवा (3 आणि अधिक म्हणजे जास्त) - आणि त्याखालील **संवाद योजना** ठेवलेल्या सर्वांची यादी देते, सर्वात महत्त्वाचे आधी. बोर्ड, प्रायोजक आणि प्रभावित लोकांना सदस्य म्हणून जोडा (लोक मॉड्यूलमधील लोकांसह) म्हणजे त्यांना ठेवता येईल.',
        ],
        'scope' => [
            'nav' => 'व्याप्ती',
            'title' => 'व्याप्ती आणि MoSCoW',
            'intro' => 'प्रोजेक्ट काय देतो, प्राधान्यानुसार लावलेले.',
            'p1' => 'व्याप्ती टॅब हा प्रोजेक्टच्या डिलिव्हरेबल्स आणि गरजांचा पाच स्तंभांतील बोर्ड आहे: Must, Should, Could, Won\'t (यावेळी) आणि प्राधान्य न दिलेले. स्तंभाच्या तळाशी असलेल्या बॉक्समध्ये टाइप करून तिथे एक जोडा, आणि त्याचे प्राधान्य बदलण्यासाठी कार्ड दुसऱ्या स्तंभात ड्रॅग करा - हा बदल इतिहासात नोंदवला जातो.',
            'p2' => 'कार्ड उघडण्यासाठी त्यावर क्लिक करा. त्याचे शीर्षक आणि प्राधान्य यासोबत त्याला स्थिती (प्रस्तावित, मान्य, सुरू, स्वीकारले किंवा सोडून दिले), तो ज्या फेजचा आहे तो, वर्णन आणि **पूर्ण झाले जेव्हा...** असते - तो पोहोचवला गेला आहे हे तुम्हाला कसे कळेल. डिलिव्हरेबल हटवल्यास RACI मॅट्रिक्समधील त्याची ओळही हटते.',
        ],
        'raci' => [
            'nav' => 'RACI',
            'title' => 'कोण काय करते: RACI',
            'intro' => 'वर लोक, बाजूला डिलिव्हरेबल्स.',
            'p1' => 'RACI टॅब हा प्रोजेक्टच्या लोकांची (स्तंभ) त्याच्या डिलिव्हरेबल्सशी (ओळी) केलेली ग्रिड आहे, म्हणून दोन्ही आवश्यक आहेत: आधी लोक टॅबवर लोक आणि व्याप्ती टॅबवर डिलिव्हरेबल्स जोडा. सोडून दिलेली डिलिव्हरेबल्स वगळली जातात.',
            'p2' => 'सेलला R, A, C, I आणि परत रिकाम्या अवस्थेत फिरवण्यासाठी त्यावर क्लिक करा. प्रत्येक डिलिव्हरेबलसाठी एकच व्यक्ती Accountable असते: दुसऱ्या व्यक्तीसाठी A सेट केल्यास आधीची व्यक्ती Responsible होते, कारण ती अजूनही काम करत आहे. कोणीही Accountable किंवा Responsible नसलेली ओळ मसुदा तयार करताना चालते, आणि डिलिव्हरेबलच्या नावाखाली चिन्हांकित केली जाते.',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'RAID लॉग आणि हीट मॅप',
            'intro' => 'काय चुकू शकते, तुम्ही काय गृहीत धरत आहात, काय चुकले आहे, कशाची वाट पाहत आहात आणि काय ठरवले आहे.',
            'p1' => 'RAID टॅब सहा प्रकारच्या नोंदी ठेवतो: जोखीम, गृहीतके, समस्या, अवलंबित्वे, निर्णय आणि शिकलेले धडे. प्रत्येकाला शीर्षक, तपशील, मालक, पुनरावलोकनाची तारीख आणि स्थिती असते - खुली किंवा बंद. वरच्या बाजूची बटणे प्रकारानुसार फिल्टर करतात आणि प्रत्येकाच्या किती नोंदी खुल्या आहेत ते दाखवतात; **बंद नोंदी दाखवा** बंद नोंदी पुन्हा यादीत आणते. नोंद करणे, बंद करणे, पुन्हा उघडणे आणि हटवणे या सर्व गोष्टी इतिहासात लिहिल्या जातात.',
            'p2' => 'जोखमीला संभाव्यता आणि परिणाम असतो, प्रत्येक पाच पायऱ्यांच्या स्केलवर, आणि संभाव्यता गुणिले परिणाम असा **गुण** असतो, 1 ते 25 पर्यंत. तिला प्रतिसाद (टाळा, कमी करा, हस्तांतरित करा, स्वीकारा किंवा वाटून घ्या) आणि ती कशी हाताळली जाईल याची योजना देखील असू शकते. समस्येला परिणाम असतो आणि ती तिकिटाशी जोडता येते, जर तुम्ही ते तिकीट उघडू शकत असाल आणि ते प्रोजेक्टच्या कंपनीचे असेल.',
            'p3' => 'हीट मॅप, **काय चुकू शकते?**, संभाव्यता आणि परिणाम दोन्ही असलेली प्रत्येक खुली जोखीम पाच-बाय-पाच ग्रिडवर ठेवतो, गुणानुसार हिरव्यापासून लाल रंगापर्यंत छटा देऊन. फक्त त्या जोखमी यादीत पाहण्यासाठी चौकोनावर क्लिक करा; साफ करण्यासाठी पुन्हा क्लिक करा किंवा **सर्व दाखवा** वापरा. दोन्ही स्केलवरील शब्द **प्रोजेक्ट्स - सेटिंग्ज - RAID** मधून येतात.',
            'p5' => '**अवलंबित्व** म्हणजे प्रोजेक्टला त्याच्या बाहेरून हवे असलेले काहीतरी - घरमालकाने फिट-आउट पूर्ण करणे, पुरवठादाराने डिलिव्हरी करणे, दुसरा संघ. त्याची तारीख म्हणजे ते कधीपर्यंत हवे आहे; ते आल्यावर बंद करा. **निर्णय** घेण्यापूर्वी नोंदवला जातो, तो कधीपर्यंत घ्यायचा आहे त्या तारखेसह, आणि घेतल्यावर बंद केला जातो, **निर्णय घेणारा** (कोणतेही नाव - प्रायोजक, मंडळ), **निर्णयाची तारीख** आणि **कारण** यासह. निर्णय लॉग म्हणून पाहण्यासाठी **निर्णय** निवडा. तारखेनंतरही खुले असलेले अवलंबित्व किंवा निर्णय प्रोजेक्टला अंबर करतो.',
            'p6' => 'जतन केलेली नोंद उघडून तिला **एस्कलेट करा** - जेव्हा प्रोजेक्ट मॅनेजरच्या वरच्या कोणाची गरज असते तेव्हा - काय हवे आहे ते सांगणाऱ्या एका ओळीसह. ती आढावा, RAID टॅब आणि पोर्टफोलिओ कार्डवर खूण करून दिसते, ती **डी-एस्कलेट** किंवा बंद होईपर्यंत; प्रोजेक्ट मॅनेजरला कळवले जाते आणि वर्कफ्लो प्रायोजकाला कळवू शकतो. **पाठपुरावा कृती** म्हणजे नोंदीतून बनवलेली प्रोजेक्टवरील कार्ये - निर्णयानंतर काय ठरले, जोखमीसाठी उपाय - आणि किती पूर्ण झाली ते लॉगवर दिसते.',
            'p4' => 'जतन केलेला **धडा** उघडा आणि त्याला मसुदा ज्ञान लेखात बदलण्यासाठी **ज्ञान** दाबा: त्याचा तपशील लेख बनतो, प्रोजेक्टची लिंक त्यात असते, आणि तो कनेक्शन्स टॅबवर जोडला जातो. तो ज्ञानमध्ये वाचा, मग प्रकाशित करा. आधीपासून असलेले तिकीट जोडण्याऐवजी त्यातून नवीन तिकीट तयार करण्यासाठी जतन केलेली **समस्या** उघडा आणि **तयार करा** दाबा: तुम्ही विनंती करणारे असता, ते समस्येच्या मालकाकडे (किंवा तुमच्याकडे) जाते, ते प्रोजेक्टच्या कंपनीचे असते, आणि समस्या व प्रोजेक्ट दोन्ही त्याला जोडले जातात. प्रत्येक गोष्ट नोंदीमागे एकदाच करता येते, आणि प्रोजेक्ट बदलण्याची परवानगी असण्याबरोबरच ज्ञान किंवा तिकिटांचा प्रवेश लागतो.',
            'p7' => '**निर्यात** (बंद नोंदी दाखवा च्या बाजूला) संपूर्ण लॉग - प्रत्येक प्रकार, खुला आणि बंद - मालक, गुण, प्रतिसाद, निर्णय आणि पाठपुरावा कृतींसह Excel वर्कबुक किंवा CSV फाइल म्हणून डाउनलोड करते.',
        ],
        'gates' => [
            'nav' => 'गेट',
            'title' => 'गेट, सहनशीलता आणि अपवाद',
            'intro' => 'टप्प्यांमध्ये चालणारा प्रोजेक्ट ज्यांना उत्तरदायी असतो ती नियंत्रणे, PRINCE2 शैलीत.',
            'p1' => 'गेट टॅबमध्ये तीन गोष्टी असतात. **बिझनेस केस** प्रोजेक्ट का करण्यासारखा आहे ते सांगते - फायदे, खर्च आणि जोखीम - आणि प्रत्येक गेटवर तिचे पुनरावलोकन व्हावे यासाठी असते. **सहनशीलता** प्रोजेक्ट निर्णयाची गरज पडण्यापूर्वी किती भरकटू शकतो ते सांगते. **टप्प्यांचे गेट** प्रत्येक टप्प्याच्या शेवटी निर्णय नोंदवतात.',
            'p2' => 'दोन सहनशीलता आहेत, आणि एक रिकामी ठेवल्यास ती बंद होते. काम अजून खुले असताना लक्ष्य समाप्ती किंवा सुरू असलेल्या टप्प्याची समाप्ती तारीख त्या दिवसांपेक्षा जास्त मागे गेली की **परवानगी असलेले उशिराचे दिवस** ओलांडले जातात. RAID लॉगमधील खुल्या जोखमीचा गुण त्यापेक्षा जास्त असल्यास **परवानगी असलेला सर्वोच्च जोखीम गुण** ओलांडला जातो.',
            'p3' => 'सहनशीलता ओलांडल्यास प्रोजेक्ट **अपवाद** ठरतो. तो टिकतो तोपर्यंत, गणलेले आरोग्य मार्गावर नाही असे असते, आढावा आणि गेट टॅबवर **सहनशीलता ओलांडली** बॅनर प्रत्येकाचे नाव देतो, आणि पोर्टफोलिओवरील प्रोजेक्टच्या कार्डावर **अपवाद** चिप असते. अपवाद प्रोजेक्ट दाखवला जाताना प्रत्येक वेळी गणले जातात, कधीही साठवले जात नाहीत, त्यामुळे प्रोजेक्ट पुन्हा सहनशीलतेत आला की ते आपोआप दूर होतात. ते फक्त गेट टूल चालू असलेल्या चालू प्रोजेक्टला लागू होतात, आणि हाताने सेट केलेले आरोग्य जसे सेट केले तसेच राहते.',
            'p4' => 'सुरू असलेल्या किंवा पूर्ण झालेल्या टप्प्यावर **निर्णय घ्या** दाबा (नियोजित टप्प्याला बटण नसते), निर्णय निवडा आणि टिपा जोडा. निर्णय, तो कोणी आणि कधी घेतला हे टप्प्यावर राहते, आणि इतिहासात लिहिले जाते. आधीच पूर्ण झालेल्या टप्प्यावर नोंदवलेला पुढे जा फक्त निर्णय नोंदवतो: तो दुसरा टप्पा सुरू करत नाही.',
            'p5' => 'निर्णयापूर्वी, गेट कनेक्शन्स टॅबवर जोडलेले **बदल** तपासतो. अजूनही खुले आणि मंजूर नसलेले - मंजुरीसाठी प्रलंबित, किंवा कोणीही सबमिट न केलेला मसुदा - गेट डायलॉगमध्ये त्यांची स्थिती आणि नियोजित सुरुवातीसह दाखवले जातात, आणि सुरू असलेल्या टप्प्यावर किती आहेत ते सांगणारी चिप असते. ही फक्त चेतावणी आहे, अडथळा नाही: निर्णय तुमचाच राहतो. तुम्ही बदल उघडू शकत असाल तरच हे दिसते.',
            'p6' => 'प्रत्येक गेटला पुढे जा च्या आधी काय खरे असले पाहिजे याची **चेकलिस्ट** असू शकते: टिक करण्यासाठी **तपासणी**; **दस्तऐवज** - प्रोजेक्टच्या **दस्तऐवज** टॅबवरील फाइल्सपैकी एक निवडून पूर्ण होते (बॅकआउट योजना, चाचणी अहवाल); नेमलेल्या व्यक्तीकडून **मंजुरी**, जिला बेलवर कळवले जाते आणि तीच ती देऊ शकते; किंवा बदलमध्ये मंजूर व्हायला हवा असा जोडलेला **बदल**. गेटला **गो-लाइव्ह गेट** बनवा आणि त्याला सुरुवातीची चेकलिस्ट मिळते - वापरकर्ता स्वीकृती चाचणी मंजूर, बॅकआउट योजना, बदल मंजूर, सपोर्ट हस्तांतरण मान्य - ठेवण्यासाठी, बदलण्यासाठी किंवा त्यात भर घालण्यासाठी. प्रत्येक बाब पूर्ण होईपर्यंत पुढे जा नाकारले जाते (थांबा कधीही नाही); प्रोजेक्ट्स - सेटिंग्ज - सामान्य यामध्ये त्याऐवजी चेतावणी करता येते, आणि मग अजून खुले असलेले गेटच्या टिपांमध्ये लिहिले जाते.',
            'go_d' => 'टप्पा बंद करतो आणि पुढचा नियोजित टप्पा सुरू करतो.',
            'go_with_conditions_d' => 'पुढे जा सारखेच, अटी टिपांमध्ये लिहिलेल्या - त्या आवश्यक आहेत.',
            'stop_d' => 'प्रोजेक्टने नियोजनाप्रमाणे पुढे जाऊ नये असे नोंदवतो. तो कोणतेही टप्पे बदलत नाही: पुढे काय करायचे ते प्रोजेक्ट चालवणाऱ्यांनी ठरवायचे आहे.',
        ],
        'templates' => [
            'nav' => 'टेम्पलेट',
            'title' => 'टेम्पलेटवरून सुरुवात करा',
            'intro' => 'आधीच नियोजित होऊन येणारा प्रोजेक्ट.',
            'p1' => 'तुम्ही प्रोजेक्ट तयार करता तेव्हा **यापासून सुरू करा** टेम्पलेट सुचवते: ऑफिस स्थलांतर, लॅपटॉप रिफ्रेश, मेल मायग्रेशन, Windows 11 रोलआउट आणि सर्व्हिस डेस्क सुधारणा हे अंगभूत येतात. एक निवडा आणि प्रोजेक्ट त्याचे टप्पे, कार्ये, व्याप्ती, जोखीम आणि सहनशीलता आधीच जागेवर असलेला तयार होतो, आणि त्याची चालवण्याची पद्धत, रंग, आयकॉन आणि उद्दिष्ट तुमच्यासाठी भरले जाते. फॉर्ममध्ये तुम्ही जे टाइप कराल ते टेम्पलेटपेक्षा वरचढ ठरते.',
            'p2' => 'टेम्पलेट त्याच्या तारखा सुरुवातीपासूनचे दिवस म्हणून ठेवते, म्हणून प्रत्येक तारीख तुम्ही दिलेल्या **सुरुवात तारखे**पासून ठरते - रिकामी ठेवल्यास आज - आणि तुम्ही एक सेट केली नाही तर लक्ष्य समाप्ती त्यामागे येते. कार्ये सामान्य कार्ये असतात, कोणालाही नेमलेले नसते, आणि काहीही पूर्ण म्हणून टिक केलेले नसते. नावाने स्थिती किंवा स्थान लागणारे मालमत्ता लक्ष्य (उदाहरणार्थ "Retired") ते नाव तुमच्या इन्स्टॉलवर असेल तरच जोडले जाते.',
            'p3' => 'स्वतःचे बनवण्यासाठी, चांगला झालेला प्रोजेक्ट उघडा आणि **टेम्पलेट** दाबा. काय ठेवायचे ते निवडा: टप्पे आणि कार्ये, व्याप्ती, जोखीम आणि गृहीतके, सहनशीलता (परवानगी असलेल्या जादा खर्चासह) आणि मालमत्ता लक्ष्ये. टेम्पलेट बदलण्यासाठी, त्यातून प्रोजेक्ट सुरू करा, प्रोजेक्ट बदला, **टेम्पलेट** दाबा आणि **तुमच्या एका टेम्पलेटची जागा घ्या** निवडा - अंगभूत टेम्पलेट्स अशा प्रकारे कॉपी करता येतात, कधीही ओव्हरराइट होत नाहीत. लोक, कंपनी, लिंक्स आणि प्रगती कधीही ठेवल्या जात नाहीत, त्यामुळे एक टेम्पलेट कोणत्याही कंपनीसाठी चालते. **प्रोजेक्ट्स - सेटिंग्ज - टेम्पलेट** सर्व दाखवते: तुम्ही कधीही न वापरणारे अंगभूत लपवा, आणि तुमचे स्वतःचे नाव बदला, बंद करा किंवा हटवा. टेम्पलेट जतन करण्यासाठी आणि सांभाळण्यासाठी टेम्पलेट परवानगी लागते; प्रोजेक्ट तयार करू शकणारे कोणीही त्यावरून सुरू करू शकते.',
            'p4' => '3.3.0 पासून टेम्पलेट योजनेची **अवलंबित्वे**, प्रत्येक टप्प्याची **गेट चेकलिस्ट** (आणि तो गो-लाइव्ह गेट आहे का - अजून मंजुरी देणारे कोणाचे नाव नसताना) आणि, तुम्ही ठेवल्यास, लक्ष्यांसह **फायदे** (बेसलाइन कधीही नाही - त्या नवीन प्रोजेक्टवर मोजल्या जातात) देखील घेऊन जाते. पाचही अंगभूत टेम्पलेट्स तिन्ही गोष्टींसह येतात.',
        ],
        'targets' => [
            'nav' => 'मालमत्ता लक्ष्ये',
            'title' => 'मालमत्ता लक्ष्ये: थेट मालमत्तेवरून प्रगती',
            'intro' => '"480 पैकी 312 लॅपटॉप बदलले", मालमत्तांवरूनच मोजलेले.',
            'p1' => 'मालमत्ता लक्ष्य प्रोजेक्टच्या आढाव्यावर असते आणि मालमत्तामधील काहीतरी मोजते: निवृत्त केलेले Latitude 5430, आता Windows 11 वर असलेली Windows मशीन्स, BitLocker चालू असलेले लॅपटॉप. मोजणी पान उघडते तेव्हा प्रत्येक वेळी केली जाते, त्यामुळे कोणीतरी मालमत्ता बदलताच प्रोजेक्ट पुढे सरकतो - कोणालाही काही टिक करण्याचे लक्षात ठेवावे लागत नाही. प्रत्येक लक्ष्य त्याच्या प्रगतीची रेषा काढते, ते सेट केल्याच्या दिवसापासून दिवसाला एक बिंदू.',
            'p2' => '**कोणत्या मालमत्ता** निवडा: एखादा प्रकार आणि/किंवा काही मजकूर असलेले फील्ड **जुळणाऱ्या** (मॉडेलमध्ये 5430 आहे), किंवा कनेक्शन्स टॅबवर **या प्रोजेक्टला जोडलेल्या**. मग **एक मालमत्ता केव्हा पूर्ण मानली जाते** ते निवडा: स्थिती, स्थान, ऑपरेटिंग सिस्टम, फीचर रिलीज, मॉडेल, उत्पादक, BitLocker किंवा TPM आवृत्ती. तुम्ही टाइप करता तसे डायलॉग किती मालमत्ता जुळतात आणि किती पूर्ण आहेत ते दाखवतो. लक्ष्य नेहमी फक्त प्रोजेक्टच्या स्वतःच्या कंपनीतील मालमत्ता मोजते.',
            'p3' => 'प्रत्येक लक्ष्याला एक तारीख असते - स्वतःची, किंवा प्रोजेक्टची लक्ष्य समाप्ती तारीख. तारीख उलटून गेलेले आणि पूर्ण न झालेले लक्ष्य प्रोजेक्टला लाल करते; ते सेट केल्याच्या दिवसापासून त्याच्या तारखेपर्यंतच्या सरळ रेषेपेक्षा 25 पेक्षा जास्त गुणांनी मागे असलेले प्रोजेक्टला अंबर करते. **अजून करायचे** उरलेल्या मालमत्ता दाखवते, प्रत्येक मालमत्तेची लिंक असते. लक्ष्य सेट करण्यासाठी आणि त्यामागे कोणत्या मालमत्ता आहेत ते पाहण्यासाठी प्रोजेक्ट बदलण्याची परवानगी असण्याबरोबरच मालमत्तेचा प्रवेश लागतो; नियम बदलल्यास त्याची रेषा पुन्हा सुरू होते.',
        ],
        'health' => [
            'nav' => 'आरोग्य',
            'title' => 'आरोग्य कसे ठरवले जाते',
            'intro' => 'योजनेवरून, कोणाच्याही मनःस्थितीवरून नाही.',
            'p1' => 'कोणी हाताने सेट केले नसल्यास, चालू प्रोजेक्टचे आरोग्य त्याच्या कार्यांवरून आणि लक्ष्य तारखेवरून दाखवले जाताना प्रत्येक वेळी ठरते. खालील आकडे डीफॉल्ट आहेत; ते **प्रोजेक्ट्स - सेटिंग्ज - आरोग्य** मध्ये बदलता येतात.',
            'green_d' => 'खालीलपैकी काहीही लागू नाही.',
            'amber_d' => 'किमान एक खुले कार्य मुदतीबाहेर आहे, मैलाचा दगड चुकला आहे किंवा अवलंबित्व अथवा निर्णय त्याच्या तारखेच्या पुढे गेला आहे (त्या दोन्हींपैकी प्रत्येक प्रोजेक्ट्स - सेटिंग्ज - आरोग्य मध्ये लाल किंवा काहीही नाही असा सेट करता येतो), लक्ष्य तारीख जवळ आहे आणि खूप कमी काम पूर्ण झाले आहे - डीफॉल्टनुसार 14 दिवसांत तीन चतुर्थांशांपेक्षा कमी पूर्ण - किंवा जोडलेल्या तिकिटांमध्ये वाढ: डीफॉल्टनुसार गेल्या 7 दिवसांत 5 किंवा अधिक तयार झाली, ज्याचा गो-लाइव्ह नंतर सहसा काहीतरी दुरुस्त करायचे आहे असा अर्थ असतो.',
            'red_d' => 'लक्ष्य तारीख उलटून गेली आहे आणि काम अजून खुले आहे, खुल्या कामापैकी खूप जास्त मुदतीबाहेर आहे - डीफॉल्टनुसार एक चतुर्थांश किंवा अधिक - किंवा प्रोजेक्ट एखाद्या सहनशीलतेच्या पुढे गेला आहे (गेट पहा). मालमत्ता लक्ष्येही मोजली जातात: तारीख उलटलेले एक प्रोजेक्टला लाल करते, खूप मागे असलेले एक हिरव्या प्रोजेक्टला अंबर करते (मालमत्ता लक्ष्ये पहा).',
            'p2' => 'ते स्वतः सेट करण्यासाठी, प्रोजेक्ट संपादित करा आणि आरोग्य निवडा; कारण सांगणारी एक ओळ जोडा. परत सोपवण्यासाठी **माझ्यासाठी ठरवा** निवडा. बंद आणि रद्द केलेल्या प्रोजेक्टना आरोग्य नसते.',
        ],
        'tasks' => [
            'nav' => 'कार्ये',
            'title' => 'प्रोजेक्ट कार्ये ही सामान्य कार्ये आहेत',
            'intro' => 'प्रत्येक व्यक्तीसाठी कामाची एकच यादी, दोन नाही.',
            'p1' => 'प्रोजेक्टमध्ये जोडलेले कार्य सामान्य कार्य असते: ते कार्ये बोर्डवर दिसते, नेमता येते, वेळापत्रकात ठेवता येते, वेळ नोंदवता येतो, त्यावर टिप्पणी करता येते आणि त्याला उपकार्ये व चेकलिस्ट देता येतात, आणि नेहमीचे ईमेल व सूचना पाठवते. प्रगती वरच्या स्तरावरील कार्ये मोजते; उपकार्ये त्यांच्या कार्यांची असतात.',
            'p2' => 'प्रोजेक्ट हटवल्याने त्याची कार्ये कधीही हटत नाहीत. ती कार्ये बोर्डवर राहतात आणि फक्त प्रोजेक्टची राहत नाहीत. फेज काढणेही असेच चालते: त्याची कार्ये प्रोजेक्टमध्येच राहतात, फक्त फेजमध्ये नाहीत.',
        ],
        'contractors' => [
            'nav' => 'कंत्राटदार',
            'title' => 'कंत्राटदारांनी केलेले काम',
            'intro' => 'जेव्हा बाहेरची फर्म प्रोजेक्टचा काही भाग करते - केबलिंग, स्थलांतर, इन्स्टॉल.',
            'p1' => 'कार्य **कंत्राटदाराला** देता येते: करार मधील पुरवठादार, आणि हवे असल्यास तिथली एखादी व्यक्ती. कार्ये बोर्डवरील कार्य विंडोमध्ये, त्यांना **कंत्राटदार** आणि **तिथला संपर्क** अंतर्गत निवडा. **नियुक्त** व्यक्ती म्हणजे इथली व्यक्ती जी कार्याची मालक असते आणि फर्मचा पाठपुरावा करते - म्हणजे कंत्राटदार कार्याला दोन्ही असतात. पुरवठादार निवडण्यासाठी करार चा प्रवेश लागतो; कार्य पाहू शकणाऱ्या कोणालाही ते कोणाकडे आहे ते दिसते.',
            'p2' => 'कंत्राटदार कार्ये योजना, टाइमलाइन आणि कार्ये बोर्डवर फर्मचे नाव घेऊन येतात, जिथे **कंत्राटदार** फिल्टर एका फर्मचे काम, सर्व कंत्राटदार काम, किंवा काहीही नाही दाखवतो. **लोक** टॅबवर, **कोणाला तरी जोडा - कंत्राटदार** फर्म, किंवा तिथली एक व्यक्ती, भूमिकेसह प्रोजेक्टवर ठेवते, म्हणजे ते RACI मॅट्रिक्स आणि स्टेकहोल्डर मॅपवर असू शकतात. लोक मधील पुरवठादाराचे पान त्यांच्याकडील प्रत्येक कार्य दाखवते.',
            'p3' => 'कंत्राटदाराचे काम **क्षमता** मध्ये कोणाच्याही भारात नसते - ते खाली सूचीबद्ध केले जाते, प्रत्येक फर्मची एक ओळ, तिची खुली कार्ये, उरलेले तास आणि किती उशिरा आहेत त्यासह. मुदतीबाहेरील कार्यांचा डायजेस्ट, AI ब्रीफिंग आणि **AI ला विचारा** हे सर्व उशिरा असलेले काम कंत्राटदाराकडे आहे का ते सांगतात, आणि AI ला विचारा कार्य कंत्राटदाराला देण्याचे सुचवू शकते.',
            'p4' => '**कंत्राटदारांना ईमेल** (प्रोजेक्ट्स - सेटिंग्ज - सामान्य) सुरुवातीला बंद असते: कंत्राटदाराचे काम इथे ट्रॅक केले जाते आणि पाठपुरावा तुम्ही स्वतः करता. ते चालू करा आणि कार्य दिल्यावर, मुदतीच्या दोन दिवस आधी, आणि चुकल्यास एकदा, फर्ममधील व्यक्तीला ईमेल जातो - तुमच्या आउटगोइंग मेलबॉक्समधून, कार्य, तारखा आणि इथे कोणाला उत्तर द्यायचे यासह. फक्त ईमेल पत्ता असलेल्या व्यक्तीची कार्येच पाठवली जातात; प्रत्येक ईमेल पाठवण्याच्या लॉगमध्ये **कंत्राटदारासाठी कार्य** म्हणून असतो.',
        ],
        'connections' => [
            'nav' => 'कनेक्शन्स',
            'title' => 'प्रोजेक्टला इतर सर्व गोष्टींशी जोडणे',
            'intro' => 'उपकरणे, बदल, तिकिटे, करार, कॉन्फिगरेशन आयटम, ज्ञान आणि समस्या.',
            'p1' => 'कनेक्शन्स टॅब प्रोजेक्टला तो ज्यांना स्पर्श करतो त्या रेकॉर्ड्सशी जोडतो: बदलले जाणारे लॅपटॉप, तो तयार करत असलेले बदल (ते मंजूर आहेत की नाही यासह), त्यामुळे झालेली तिकिटे, तो ज्यावर अवलंबून आहे ते पुरवठादार करार, CMDB मधील सिस्टम्स, ज्ञान मधील रनबुक्स आणि तो सोडवण्यासाठी अस्तित्वात असलेल्या समस्या. शोधण्यासाठी प्रकाराखालील बॉक्समध्ये टाइप करा, आणि जोडण्यासाठी निकाल निवडा. आढावा प्रत्येकाचे किती जोडलेले आहेत ते दाखवतो.',
            'p2' => 'प्रकाराचे मॉड्यूल उघडू शकत असाल तरच तो प्रकार दिसतो, आणि दुसऱ्या टोकाचे रेकॉर्ड उघडू शकत असाल तरच लिंक दिसते. एकापेक्षा जास्त कंपन्या असलेल्या इन्स्टॉलवर, उपकरणे, बदल, तिकिटे, समस्या आणि कॉन्फिगरेशन आयटम प्रोजेक्टच्या स्वतःच्या कंपनीचे असले पाहिजेत. लिंक काढल्याने रेकॉर्ड कधीही बदलत नाही, आणि दोन्ही प्रोजेक्टच्या इतिहासात लिहिल्या जातात.',
            'p3' => 'प्रत्येक रेकॉर्ड स्वतःच्या बाजूनेही त्याचे प्रोजेक्ट्स दाखवतो. **समस्ये**ला **प्रोजेक्ट्स** पॅनेल असते जे ती ज्या प्रोजेक्टचा भाग आहे त्यांची यादी त्यांच्या आरोग्य आणि प्रगतीसह देते, आणि तिथूनच चालू प्रोजेक्टशी जोडण्यासाठी **प्रोजेक्टमध्ये जोडा** असते - प्रोजेक्टच्या कनेक्शन्स टॅबवरील लिंकसारखीच.',
        ],
        'calendar' => [
            'nav' => 'दिनदर्शिकेवर',
            'title' => 'दिनदर्शिकेवरील प्रोजेक्ट तारखा',
            'intro' => 'लक्ष्य समाप्ती तारखा, टप्प्यांचे शेवट आणि मैलाचे दगड, जिथे बाकी संघ आधीच पाहतो.',
            'p1' => 'प्रत्येक प्रस्तावित किंवा सक्रिय प्रोजेक्ट त्याची लक्ष्य समाप्ती तारीख सामायिक दिनदर्शिकेवर "Project due" म्हणून ठेवतो, आणि बंद न झालेला प्रत्येक टप्पा, फेज किंवा स्प्रिंट त्याची समाप्ती तारीखही तिथे ठेवतो, तसेच प्रत्येक मैलाचा दगड गाठेपर्यंत. त्या Projects नावाच्या श्रेणीतील दिवसभराच्या नोंदी असतात, ज्यांचे नाव किंवा रंग तुम्ही दिनदर्शिकेवर बदलू शकता. प्रोजेक्टमध्ये तारीख बदला आणि दिनदर्शिका तिच्यामागे येते; टप्पा बंद करा, किंवा प्रोजेक्ट होल्डवर ठेवा, बंद करा किंवा रद्द करा, आणि त्याच्या नोंदी जातात. **प्रोजेक्ट्स - सेटिंग्ज - सामान्य** दिनदर्शिका सर्व दाखवते, फक्त लक्ष्य समाप्ती तारखा दाखवते, की काहीच नाही ते ठरवते.',
            'p2' => 'नोंदी प्रोजेक्ट्स लिहितात, म्हणून दिनदर्शिकेवर एखाद्यात केलेला बदल कोणताही प्रोजेक्ट बदलला की पुढच्या वेळी बदलला जातो. त्यांचे शब्द इंग्रजीत आहेत, इतर स्वयंचलित नोंदींप्रमाणे. दिनदर्शिकेच्या नोंदींना कंपनी नसते, त्यामुळे एकापेक्षा जास्त कंपन्या असलेल्या इन्स्टॉलवर दिनदर्शिका उघडू शकणाऱ्या प्रत्येकाला प्रत्येक प्रोजेक्टच्या तारखा दिसतात.',
        ],
        'alerts' => [
            'nav' => 'सूचना आणि वर्कफ्लो',
            'title' => 'सूचना, आणि वर्कफ्लोमधील प्रोजेक्ट्स',
            'intro' => 'काही गोष्टीसाठी प्रोजेक्ट मॅनेजरची गरज असते तेव्हा त्याला कळते, आणि वर्कफ्लो त्यावर कृती करू शकतो.',
            'p1' => 'सूचना बेल प्रोजेक्टच्या मॅनेजरला सांगते जेव्हा त्याचे आरोग्य बदलते (हिरवे, अंबर किंवा लाल, ठरवलेले किंवा हाताने सेट केलेले), जेव्हा तो वेळ किंवा जोखीम सहनशीलतेच्या पुढे जातो, जेव्हा टप्पा, फेज किंवा स्प्रिंट 7 दिवसांत संपतो आणि पुन्हा आदल्या दिवशी, जेव्हा मैलाचा दगड 7 दिवस दूर असतो, आदल्या दिवशी, आणि चुकल्यास, आणि जेव्हा कोणी बदल विनंती तयार करते, मंजूर करते किंवा नाकारते. यातील प्रत्येक गोष्ट घडते तेव्हा एकदाच सांगितली जाते: लाल राहणारा प्रोजेक्ट दर तासाला वाजत नाही, आणि दूर होऊन परत आलेले उल्लंघन नवीन बातमी असते. स्वतः केलेल्या बदलाबद्दल कोणालाही कळवले जात नाही. प्रत्येक व्यक्ती हे बंद करू शकते, किंवा टप्पा बंद होतो किंवा मैलाचा दगड गाठला जातो तेव्हा बेल चालू करू शकते, **प्राधान्ये - सूचना** मध्ये.',
            'p2' => 'याच क्षणांना **वर्कफ्लो** मध्ये ट्रिगर आहेत: प्रोजेक्टचे आरोग्य बदलते, सहनशीलतेचे उल्लंघन होते, टप्पा बंद होतो, टप्पा लवकरच संपतो, मैलाचा दगड येत आहे, चुकला किंवा गाठला, बदल विनंती तयार किंवा ठरवली जाते, आणि प्रोजेक्ट तयार, अद्यतनित किंवा हटवला जातो. वर्कफ्लो प्रोजेक्ट लाल झाल्यावर Teams किंवा Slack वर पोस्ट करू शकतो, सहनशीलतेचे उल्लंघन झाल्यावर तिकीट तयार करू शकतो, किंवा टप्पा बंद झाल्यावर मंडळाला ईमेल करू शकतो, प्रोजेक्टचे नाव, कोड, आरोग्य, मॅनेजर आणि तारखा वापरून.',
            'p3' => 'आरोग्य आणि सहनशीलता योजनेवरून ठरतात, म्हणून कोणीतरी पाहिले पाहिजे. प्रोजेक्टवर काहीही जतन केल्यास लगेच पाहिले जाते; अन्यथा शेड्यूल केलेला वर्कफ्लो जॉब ते करतो (cron/workflow_scheduled.php, तासाला एकदा पुरेसे), आणि शेड्यूल केलेले जॉब नसलेल्या इन्स्टॉलवर, पोर्टफोलिओ उघडल्यास जास्तीत जास्त दर 15 मिनिटांनी पाहिले जाते. रात्रभरात मुदतीबाहेर गेलेले कार्य यापैकी जे आधी येईल त्याला कळते.',
            'p4' => '**स्मरणपत्रे.** प्रत्येक प्रोजेक्ट मॅनेजरला त्यांच्या सक्रिय प्रोजेक्टच्या **मुदतीबाहेरील कार्यांची** यादी असलेली बेल मिळते - सोमवारी साप्ताहिक, रोज किंवा कधीही नाही (प्रोजेक्ट्स -> सेटिंग्ज -> सामान्य, *मुदतीबाहेरील कार्यांचा डायजेस्ट*). आणि जेव्हा प्रस्ताव, बदल विनंती, गेट मंजुरी किंवा अहवालाचा मसुदा निर्णयासाठी **3 दिवस** थांबलेला असतो, तेव्हा तो ठरवणाऱ्यांना आठवण दिली जाते - *तुमच्या मंजुरीची अजून वाट पाहत आहे* - आणि पुन्हा दर 3 दिवसांनी (*आठवण द्या*; 0 = स्मरणपत्रे नाहीत). 45 दिवसांपेक्षा जुन्या कशाचीही आठवण दिली जात नाही.',
            'p5' => 'बेल हेही सांगते: कोणी RAID नोंद एस्कलेट केली तेव्हा प्रोजेक्ट मॅनेजरला; नवीन प्रस्तावाबद्दल मंजूर करणाऱ्यांना, आणि निर्णयाबद्दल तो मांडणाऱ्याला; गेटवर नेमलेल्या व्यक्तीला जेव्हा तिच्या मंजुरीची गरज असते; पुनरावलोकन देय असताना, बंद झाल्यानंतरही, फायद्याच्या मालकाला आणि प्रोजेक्ट मॅनेजरला; आणि शेड्यूल केलेल्या अहवालाचा मसुदा तयार झाल्यावर प्रोजेक्ट मॅनेजरला. यातील प्रत्येक, मुदतीबाहेरील डायजेस्ट आणि आठवणी हे **वर्कफ्लो** मध्येही ट्रिगर आहेत.',
        ],
        'budget' => [
            'nav' => 'बजेट',
            'title' => 'बजेट: नियोजित विरुद्ध प्रत्यक्ष',
            'intro' => 'प्रोजेक्टसाठी किती खर्च अपेक्षित होता, प्रत्यक्षात किती झाला आणि दोघांत किती फरक आहे.',
            'p1' => 'बजेट टॅब (टप्प्यांच्या प्रोजेक्ट्ससाठी चालू असतो; इतरांसाठी टूल्स अंतर्गत चालू करा) नियोजित बजेट, प्रत्यक्ष खर्च, शिल्लक रक्कम आणि किती वापरले गेले ते दाखवतो. ज्या गोष्टींवर खर्च अपेक्षित आहे - हार्डवेअर, परवाने, पुरवठादार - त्या प्रत्येकासाठी एक **बजेट ओळ** जोडा, त्यात काय नियोजित होते आणि किती खर्च झाला ते भरा. ओळीला कनेक्शन्स टॅबवर जोडलेल्या कराराचे नाव देता येते: तिचा प्रत्यक्ष खर्च रिकामा ठेवल्यास कराराचे मूल्य वापरले जाते. त्यावर प्रोजेक्टच्या कंपनीचे कॉस्ट सेंटरही देता येते.',
            'p2' => '**श्रम** म्हणजे प्रोजेक्टच्या कार्यांवर नोंदवलेला वेळ. प्रोजेक्ट्स - सेटिंग्ज - बजेट ठरवते की तो तासांमध्ये दाखवायचा, एका तासाच्या दराने किंमत लावून दाखवायचा (जो प्रोजेक्ट बदलू शकतो), की प्रत्येक विश्लेषकाच्या दराने. प्रत्येक दर एका तारखेपासून लागू होतो, त्यामुळे नवीन दरामुळे आधी नोंदवलेल्या वेळाची किंमत पुन्हा ठरत नाही, आणि सेटिंग बदलल्याने काहीही पुन्हा लिहिले जात नाही - वेळ वेळ म्हणूनच साठवला जातो.',
            'p4' => '**पैसा कुठे जातो** हा चार्ट प्रत्येक श्रेणीसाठी नियोजित विरुद्ध प्रत्यक्ष दाखवतो, श्रमाला किंमत लावलेली असल्यास त्यासह. **तक्ता** तीच आकडेवारी तक्त्याच्या रूपात दाखवतो.',
            'p5' => 'ओळीवर **केव्हा** हेही सांगता येते: पैसे कोणत्या तारखेला जाणे नियोजित आहे आणि ते कोणत्या तारखेला गेले. **कालानुसार खर्च** हे दिवसागणिक जोडून दाखवतो - आतापर्यंत नियोजित आणि खर्च झालेले - तसेच आजपासून अंतिम लक्ष्य तारखेपर्यंत तुटक रेषेतील **अंदाज** आणि मोजमापासाठी रेषा म्हणून बजेट, ताज्या बेसलाइनचे बजेट आणि अतिरिक्त खर्चाची सहनशीलता. **अंदाज** म्हणजे प्रोजेक्टला आता किती खर्च अपेक्षित आहे: प्रत्येक ओळीचा स्वतःचा अंदाज (तो टाइप करा, नाहीतर नियोजित आणि खर्च झालेल्यांपैकी मोठा), अधिक श्रम - नोंदवलेले, आणि उघड्या कार्यांच्या अंदाजांनुसार अजून यायचे, आजच्या दराने किंमत लावलेले. प्रत्यक्ष खर्च नसलेली श्रम ओळ म्हणजे श्रमाचे नियोजन, त्यामुळे श्रम कधीही दोनदा मोजले जात नाही. अंदाज मोजले जावेत का, आणि **अनुमत अतिरिक्त खर्च** प्रत्यक्ष झालेला खर्च मोजतो की अंदाज - जो लवकर इशारा देतो - हे प्रोजेक्ट्स - सेटिंग्ज - बजेट ठरवते.',
            'p3' => 'प्रत्येक प्रोजेक्ट तयार करताना निवडलेले **चलन** स्वतःकडे ठेवतो, आणि वेगवेगळ्या चलनांतील रकमा कधीही एकत्र जोडल्या जात नाहीत: दुसऱ्या चलनातील करार त्याच्या ओळीवर दिसतो पण मोजला जात नाही. प्रोजेक्ट्स - सेटिंग्जमध्ये प्रोजेक्ट्सना निवड करू दिली असल्यास, चलन बटण प्रोजेक्टचे लेबल बदलते - ते रूपांतर करत नाही. गेट्स टॅबवर **अनुमत अतिरिक्त खर्च** खर्चाची सहनशीलता ठरवतो: बजेटपेक्षा त्याहून जास्त खर्च झाल्यास प्रोजेक्ट अपवाद ठरतो आणि मार्गावर नाही असा दिसतो.',
            'p6' => '**अर्न्ड व्हॅल्यू** तीन रेषांची तुलना करते: प्लॅन्ड व्हॅल्यू (बजेट ज्या प्रकारे खर्च होणे नियोजित होते, ओळींच्या नियोजित तारखांनुसार), अर्न्ड व्हॅल्यू (बजेट गुणिले पूर्ण झालेल्या कामाचा वाटा - अंदाजित तासांनुसार, अंदाज नसल्यास कार्यांनुसार) आणि प्रत्यक्ष खर्च. **CPI** म्हणजे अर्न्ड व्हॅल्यू भागिले प्रत्यक्ष खर्च - 1 पेक्षा कमी असल्यास, पूर्ण झालेल्या कामाला अपेक्षेपेक्षा जास्त खर्च आला आहे; **SPI** म्हणजे अर्न्ड व्हॅल्यू भागिले प्लॅन्ड व्हॅल्यू - 1 पेक्षा कमी असल्यास, नियोजनापेक्षा मागे; **पूर्णत्वाचा अंदाज** म्हणजे बजेट भागिले CPI.',
        ],
        'benefits' => [
            'nav' => 'लाभ',
            'title' => 'लाभ: प्रोजेक्टचा फायदा झाला का?',
            'intro' => 'प्रोजेक्टने काय सुधारणे अपेक्षित आहे, सुरुवातीच्या स्थितीपासून मोजलेले - आणि तो बंद झाल्यानंतर पुनरावलोकन केलेले, कारण बहुतेक लाभ तेव्हाच मिळतात.',
            'p1' => '**लाभ** टॅब (टप्प्यांच्या प्रोजेक्ट्ससाठी चालू असतो; इतरांसाठी टूल्स अंतर्गत चालू करा) प्रोजेक्टने काय सुधारावे ते यादीत दाखवतो. एक **जोडा**: काय सुधारते, ते कसे आणि कोणत्या एककात मोजले जाते, कोणती दिशा चांगली (जास्त की कमी), **बेसलाइन** (आज कुठे आहे), **लक्ष्य** आणि ते कोणत्या तारखेपर्यंत गाठायचे, एक मालक आणि पुनरावलोकन केव्हा होते. प्रत्येक लाभ बेसलाइन, आत्ताचे आणि लक्ष्य शेजारी शेजारी, किती प्रगती झाली त्यासह, आणि यापैकी एक स्थिती दाखवतो: अजून मोजले नाही, प्रगतीत, साध्य झाले, किंवा लक्ष्य तारीख चुकली.',
            'p2' => '**नोंदवा** एक मोजमाप जोडते - एक मूल्य आणि ते मोजल्याची तारीख. सर्वात ताजे म्हणजे "आत्ताचे". ते पुनरावलोकन तारखेला किंवा जवळ (14 दिवस आधीपर्यंत) नोंदवल्यास ते पुनरावलोकन म्हणून गणले जाते, आणि पुढचे पुनरावलोकन लाभाच्या अंतराने पुढे जाते; अंतर 0 असल्यास ते एकदाच पुनरावलोकन केले जाते. **इतिहास** प्रत्येक मोजमाप दाखवतो. लाभावर यापुढे लक्ष ठेवण्याची गरज नसल्यास, तो संपादित करा आणि **या लाभाचे पुनरावलोकन थांबवा** टिक करा.',
            'p3' => 'पुनरावलोकन तारीख आली की घंटा लाभाच्या मालकाला आणि प्रोजेक्ट मॅनेजरला कळवते (प्रोजेक्ट्स - सेटिंग्ज - सामान्य मध्ये ते फक्त मालकापुरते करता येते) - **प्रोजेक्ट बंद झाल्यानंतरही**; रद्द केलेल्या प्रोजेक्टचे पुनरावलोकन होत नाही. आढावा आणि पोर्टफोलिओ कार्ड देय असलेली पुनरावलोकने दाखवतात, आणि अहवाल टॅबवरील **समाप्ती** अहवालात प्रत्येक लाभ असतो: काय साध्य झाले आणि काय अजून यायचे आहे.',
        ],
        'intake' => [
            'nav' => 'प्रस्ताव आणि मंजुरी',
            'title' => 'प्रोजेक्ट प्रस्तावित करणे आणि मंजूर करणे',
            'intro' => 'फॉर्मवरील "आम्हाला मिळेल का..." पासून मंजूर प्रोजेक्टपर्यंत, त्यामागील कारण लिहून ठेवलेले.',
            'p1' => 'कोणताही फॉर्म प्रोजेक्ट प्रस्तावित करू शकतो. **फॉर्म** मध्ये फॉर्म उघडा, **पुढे काय होते** वर जा आणि "सबमिट केल्यावर" (किंवा आधी मंजूर होणाऱ्या फॉर्मसाठी "मंजूर झाल्यावर") अंतर्गत **प्रोजेक्ट प्रस्ताव तयार करा** जोडा. त्याचे बॉक्स रिकामे ठेवल्यास प्रोजेक्टचे नाव फॉर्म आणि पाठवणाऱ्याच्या नावावरून ठरते, त्याचा सारांश म्हणजे त्यांची उत्तरे आणि तो त्यांच्या कंपनीचा असतो; किंवा ते भरा - नाव, गरज का आहे, अंदाजित खर्च, अपेक्षित लाभ, हवी असलेली तारीख, तो कसा चालवला जातो, प्राधान्य, प्रोजेक्ट मॅनेजर - उत्तरे वापरून, जसे {{submission.fields.Budget}}. हीच कृती **वर्कफ्लो** मधील कोणत्याही नियमात चालते.',
            'p2' => 'प्रस्तावाच्या आढाव्यावर **प्रस्ताव** पॅनेल दिसते - कोणी प्रस्तावित केला आणि कोणत्या फॉर्मवर, अंदाजित खर्च, अपेक्षित लाभ आणि गरज का आहे - आणि पोर्टफोलिओवर **मंजुरीची प्रतीक्षा** चिप आणि दृश्य. मंजूर होईपर्यंत तो प्रस्तावित राहू शकतो किंवा रद्द होऊ शकतो, यापेक्षा काही नाही. मंजूर करणारा **मंजूर करा** दाबतो (तो प्रस्तावित राहतो आणि प्रोजेक्ट मॅनेजर तो सुरू करतो, किंवा लगेच सुरू होतो - ही एक सेटिंग आहे) किंवा कारणासह **नाकारा** (तो रद्द होतो; काहीही हटवले जात नाही). नवीन प्रस्तावाबद्दल मंजूर करणाऱ्यांना घंटेवर कळते; ज्याने प्रस्तावित केला त्याला निर्णय कळतो, आणि "प्रोजेक्ट प्रस्ताव मंजूर किंवा नाकारला जातो" यावरील वर्कफ्लो फॉर्मवर विचारणाऱ्या कोणाला तरी ईमेल पाठवू शकतो.',
            'p3' => 'प्रोजेक्ट्स - सेटिंग्ज - सामान्य ठरवते की कोणत्या नवीन प्रोजेक्ट्सना मंजुरी लागते (फॉर्मवर प्रस्तावित केलेले - डीफॉल्ट -, प्रत्येक नवीन प्रोजेक्ट, किंवा कोणतेही नाही), कोण मंजूर करतो (प्रोजेक्ट्स व्यवस्थापित करणारे लोक, किंवा नाव दिलेली व्यक्ती - प्रोजेक्ट्स व्यवस्थापित करा परवानगी असलेले नेहमी निर्णय घेऊ शकतात) आणि मंजुरीमुळे काय होते. सेटिंग चालू करण्यापूर्वी तयार केलेल्या प्रोजेक्ट्सवर कधीही परिणाम होत नाही.',
        ],
        'control' => [
            'nav' => 'बदल नियंत्रण',
            'title' => 'बदल नियंत्रण: बेसलाइन आणि बदल विनंत्या',
            'intro' => 'काय मान्य झाले, तेव्हापासून योजना किती भरकटली आणि ती हलवायला कोणी मान्यता दिली.',
            'p1' => '**बेसलाइन** मान्य झालेली योजना जशी होती तशी नोंदवते: सुरुवात आणि अंतिम लक्ष्य तारीख, नियोजित बजेट, कार्ये आणि अंदाजित तास, Must बाबी, आणि प्रत्येक टप्पा, माइलस्टोन आणि बजेट ओळ. बदल नियंत्रण टॅब (टप्प्यांच्या प्रोजेक्ट्ससाठी चालू असतो; इतरांसाठी टूल्स अंतर्गत चालू करा) ती आजच्या योजनेशी तुलना करतो - शेवटच्या तारखेवर **+17 दिवस**, बजेटवर **+£4,950 (+20%)** - आणि काय हलले ते बाबीनुसार दाखवतो: दोन आठवडे उशिराचा माइलस्टोन, वाढलेली बजेट ओळ, जोडलेली Must बाब. त्या बेसलाइनशी मोजण्यासाठी **तुलना करा** अंतर्गत जुनी बेसलाइन निवडा. हाताने एक घेण्यासाठी **बेसलाइन** दाबा, हवे असल्यास लेबलसह; बेसलाइन कधीही संपादित केली जात नाही, त्याऐवजी नवीन घेतली जाते.',
            'p2' => '**बदल विनंती** मान्य योजना हलवण्यापूर्वी तसे करण्याची परवानगी मागते: बदल काय आहे, का, आणि त्याचा वेळ (दिवस, + उशीर), खर्च (+ जास्त, - बचत) आणि व्याप्तीवर काय परिणाम होतो. **मांडा** दाबा. ज्याने ती मांडली तो ती प्रतीक्षेत असताना संपादित किंवा मागे घेऊ शकतो. ती **मंजूर** झाल्यावर नवीन बेसलाइन घेतली जाते - बदललेली योजना मान्य योजना बनते - आणि डीफॉल्टनुसार अंतिम लक्ष्य तारीख त्यातील दिवसांनी हलते आणि तिचा खर्च तिच्या नावाची बजेट ओळ बनतो. **नाकारल्याने** निर्णय नोंदवला जातो आणि काहीही बदलत नाही. विनंत्या कधीही हटवल्या जात नाहीत: योजना का हलली त्याची ती नोंद आहे, आणि प्रत्येक इतिहासात असते. दुसऱ्याने मांडलेल्या विनंतीबद्दल प्रोजेक्ट मॅनेजरला कळते, आणि प्रतीक्षेतील विनंती आढावा आणि पोर्टफोलिओ कार्डवर दिसते.',
            'p3' => 'प्रोजेक्ट्स - सेटिंग्ज - सामान्य ठरवते की ते तुमच्यासाठी कसे चालते: प्रोजेक्ट सक्रिय झाल्यावर बेसलाइन **आपोआप** घ्यावी, किंवा तेव्हा **आणि** प्रत्येक टप्पा सुरू होताना (डीफॉल्ट), किंवा फक्त हाताने; बदल विनंत्यांवर **कोण निर्णय घेते** - प्रोजेक्ट मॅनेजर किंवा प्रोजेक्ट्स व्यवस्थापित करणारे कोणीही (डीफॉल्ट), प्रोजेक्टच्या संघातील कोणीही, किंवा फक्त प्रोजेक्ट्स व्यवस्थापित करणारे लोक; विनंती मांडणारी व्यक्ती ती स्वतः **ठरवू** शकते का; आणि मंजुरीने **योजनाही हलते** का की फक्त नवीन बेसलाइन घेतली जाते.',
        ],
        'announce' => [
            'nav' => 'व्यत्यय जाहीर करणे',
            'title' => 'सेवा स्थितीवर व्यत्यय जाहीर करणे',
            'intro' => '"शिफ्टिंग डे: शनिवारी फोन बंद" - ते घडण्यापूर्वी सर्वांना सांगितले जाते.',
            'p1' => 'कनेक्शन्स टॅबवर सेवा स्थिती उघडू शकणाऱ्या लोकांसाठी **सेवा स्थिती** पॅनेल आहे. **घोषित करा** दाबा, शीर्षक, सुरुवात आणि शेवट केव्हा, लोकांना काय माहीत असावे आणि प्रभावित सेवा द्या (दुसरा परिणाम निवडला नाही तर देखभाल). डीफॉल्टनुसार ते **नियोजित देखभाल** बनते: ते सेवा स्थितीवर लगेच आगामी म्हणून दिसते, सुरुवातीला त्या सेवांवर घटना बनते आणि शेवटी निराकरण होते. सुरू होण्यापूर्वी फुली दाबून ते मागे घ्या. पॅनेल प्रोजेक्टने जाहीर केलेले सर्व दाखवते, आणि जाहीर करणे व मागे घेणे दोन्ही प्रोजेक्टच्या इतिहासात जातात.',
            'p2' => '**प्रोजेक्ट्स - सेटिंग्ज - सामान्य - सेवा स्थितीवर व्यत्यय जाहीर करा** ठरवते की घोषित करा काय करते: नियोजित देखभाल म्हणून (डीफॉल्ट), लगेच घटना म्हणून, किंवा अजिबात नाही. प्रोजेक्ट हटवल्याने त्याने जाहीर केलेले सेवा स्थितीवर राहते: ते खऱ्या सेवांवरचे खरे काम आहे.',
        ],
        'reports' => [
            'nav' => 'ब्रीफिंग आणि अहवाल',
            'title' => 'AI प्रोजेक्ट मॅनेजर: ब्रीफिंग आणि अहवाल',
            'intro' => 'या आठवड्यात कशाकडे लक्ष द्यायचे याची ब्रीफिंग, आणि तुम्ही तपासण्यासाठी तयार केलेले स्थिती अहवाल.',
            'p1' => '**प्रोजेक्ट्स - सेटिंग्ज - AI** मध्ये AI प्रदाता सेट केल्यावर, प्रोजेक्टच्या आढाव्यावर **ब्रीफिंग** पॅनेल असते. **माहिती द्या** दाबा आणि AI प्रोजेक्ट वाचते - तारखा, आरोग्य, सहनशीलता, टप्पे, मुदत संपलेली आणि येणारी कार्ये, जोखीम आणि समस्या, बजेट आणि गेल्या आठवड्यातील बदल, आणि 3.3.0 पासून प्राधान्य, माइलस्टोन, अंदाज, निर्णय, बदल विनंत्या, अर्न्ड व्हॅल्यू, लाभ, कोणती कार्ये इतरांवर अवलंबून आहेत आणि क्रिटिकल पाथ, अजून उघड्या गेट चेकलिस्ट बाबी आणि भागधारक नकाशाही - आणि कशाकडे लक्ष हवे त्याचे चार ते सात छोटे मुद्दे लिहिते, सर्वात महत्त्वाचे आधी. ताजी ब्रीफिंग सर्वांसाठी पानावर राहते; नवीन ब्रीफिंग जास्तीत जास्त दर 10 मिनिटांनी तयार होते, कारण प्रत्येक ब्रीफिंग म्हणजे प्रदात्याला केलेला एक कॉल.',
            'p2' => '**अहवाल** टॅबमध्ये प्रोजेक्टचे हायलाइट, अपवाद, चेकपॉइंट आणि समाप्ती अहवाल असतात. प्रकार आणि कालावधी निवडा आणि AI ने लिहावा म्हणून **मसुदा** दाबा, किंवा स्वतः सुरू करण्यासाठी **लिहा**. प्रोजेक्ट बदलू शकणारे कोणीही मसुदा तयार करू शकतो, संपादित करू शकतो आणि हटवू शकतो. **मंजूर करणे** प्रोजेक्ट मॅनेजर, प्रोजेक्ट तयार करणारी व्यक्ती आणि प्रोजेक्ट्स व्यवस्थापित करणाऱ्या लोकांसाठी आहे - मंजूर अहवाल अंतिम असतो, संपादित करता येत नाही, आणि बोर्ड तोच वाचते. प्रत्येक अहवाल दाखवतो की AI ने मसुदा केला का आणि त्यानंतर कोणी व्यक्तीने बदलला का. **कॉपी** तो ईमेल किंवा दस्तऐवजात पेस्ट करण्यासाठी क्लिपबोर्डवर ठेवते.',
            'p3' => 'विचारणारी व्यक्ती जे पाहू शकते तेच AI पाहते: त्या मॉड्यूल्स नसलेल्या व्यक्तीसाठी तिकिटे, बदल आणि सेवा स्थिती वगळली जातात. प्रोजेक्टमध्ये जे आहे तेच सांगावे, आणि काही माहीत नसेल तिथे तसे सांगावे असे त्याला सांगितले आहे - पण तरीही ते चुकू शकते, म्हणून मंजूर करण्यापूर्वी मसुदा वाचा. तुम्ही FreeITSM ज्या भाषेत वापरता त्या भाषेत ते लिहिते. लोकांनी प्रोजेक्टमध्ये टाईप केलेला मजकूर डेटा म्हणून दिला जातो, सूचना म्हणून कधीही नाही.',
            'p4' => '**अहवाल आपोआप तयार करा** (अहवाल टॅबवर): प्रोजेक्ट सक्रिय असताना दर आठवड्याला, दर दोन आठवड्यांनी किंवा दर महिन्याला, कालावधीच्या सुरुवातीला हायलाइट, चेकपॉइंट किंवा अपवाद अहवालाचा मसुदा तयार होतो - AI सेट केले असल्यास त्याने, नाहीतर तो लिहिण्यासाठीची तथ्ये घेऊन - आणि प्रोजेक्ट मॅनेजरला कळवले जाते. तो प्रोजेक्ट मॅनेजरच्या प्रवेशाने लिहिला जातो, त्यामुळे त्यात फक्त तेच असते जे ते पाहू शकतात. तो कधीही आपोआप मंजूर होत नाही. मंजूर अहवालावरील **पाठवा** तो तुम्ही टिक केलेल्या प्रोजेक्ट सदस्यांना आणि इतर पत्त्यांना ईमेल करते, वर ऐच्छिक टीपेसह; अहवाल तो कोणाला आणि केव्हा गेला ते दाखवतो.',
        ],
        'assistant' => [
            'nav' => 'AI ला विचारा',
            'title' => 'AI ला विचारा - प्रोजेक्ट असिस्टंट',
            'intro' => 'एका प्रोजेक्टबद्दल संवाद, तो वाचू शकणाऱ्या आणि बदल सुचवू शकणाऱ्या AI प्रोजेक्ट मॅनेजरसोबत.',
            'p1' => 'प्रोजेक्टवर, **AI ला विचारा** (वर उजवीकडे) असिस्टंट स्लाइड करून आणते. तुम्ही जसे वाचू शकता तसे ते प्रोजेक्ट वाचते - तुम्ही स्वतः उघडू शकत नाही असे काहीही नाही - आणि सोप्या शब्दांत उत्तर देते, मग तुम्ही कधी प्रोजेक्ट चालवला नसेल किंवा PRINCE2 तोंडपाठ असेल. प्रोजेक्ट्स - सेटिंग्ज - AI मध्ये AI प्रदाता सेट केल्यावरच.',
            'p2' => 'प्रोजेक्टची तयारी किती झाली आहे हे ते ओळखते. फक्त नाव असलेल्या प्रोजेक्टला **कोच** मिळतो: हे कशाबद्दल आहे, पूर्ण झाले म्हणजे कसे दिसते, साधारण केव्हा, कोण सहभागी आहे - आणि मग प्रस्तावित सेट-अप: ध्येय, तारखा, चालवण्याची पद्धत, टप्पे, सुरुवातीची कार्ये, माइलस्टोन आणि संभाव्य जोखीम. चालू प्रोजेक्टला **सर्व काही सांभाळण्यात** मदत मिळते: काय मुदत ओलांडले आहे, मोठी जोखीम, चुकलेले माइलस्टोन, प्रतीक्षेतील बदल विनंत्या. संवादाखालील बटणे सुरुवातीसाठी प्रश्न सुचवतात.',
            'p3' => '**ते प्रोजेक्ट कधीही स्वतःहून बदलत नाही.** सुचवलेले बदल एका कार्डवर येतात - प्रत्येकासाठी एक बॉक्स, सर्व टिक केलेले - **लागू करा** आणि **फेटाळा** सह. लागू करा टिक केलेले बदल अगदी तुम्ही स्क्रीनवर केल्यासारखे, तुमच्या परवानग्यांसह करते, आणि ते इतिहासात तुमचे म्हणून दिसतात. तुम्हाला प्रोजेक्ट बदलण्याची परवानगी नसेल तर ते फक्त सल्ला देते.',
            'p4' => '**ते लक्षात ठेवते.** प्रोजेक्टवरील तुमचा संवाद जतन केला जातो, आणि जुने भाग एका छोट्या स्मृतीत घडी करून ठेवले जातात, त्यामुळे तुम्ही जिथे थांबला होता तिथून पुढे सुरू करता; काही काळाने परतल्यावर तेव्हापासून काय बदलले आहे त्यापासून ते सुरू होते. **पुन्हा सुरू करा** ते विसरते. प्रोजेक्ट्स - सेटिंग्ज - सामान्य - *AI असिस्टंटची स्मृती* प्रत्येकाचा स्वतःचा संवाद ठेवण्याऐवजी संपूर्ण प्रोजेक्ट संघासाठी एकच संवाद करते.',
        ],
        'companies' => [
            'nav' => 'कंपन्या',
            'title' => 'प्रोजेक्ट्स आणि कंपन्या',
            'intro' => 'प्रत्येक प्रोजेक्ट एका कंपनीचा असतो.',
            'p1' => 'एकापेक्षा जास्त कंपन्या असलेल्या इन्स्टॉलमध्ये, प्रोजेक्ट तो ज्या कंपनीत तयार केला (किंवा तुम्ही निवडलेल्या) तिचा असतो, आणि त्याची कार्येही तिथलीच असतात. तुम्हाला दिसणाऱ्या कंपन्यांचेच प्रोजेक्ट्स तुम्हाला दिसतात, आणि सर्व कंपन्या दृश्य ते एकत्र दाखवते. दुसऱ्या कंपनीचे कार्य प्रोजेक्टमध्ये ठेवता येत नाही.',
        ],
        'settings' => [
            'nav' => 'सेटिंग्ज',
            'title' => 'सेटिंग्ज आणि परवानग्या',
            'intro' => 'प्रोजेक्ट्स कोण तयार, बदल आणि हटवू शकते, आणि मॉड्यूल वापरत असलेले शब्द व मर्यादा.',
            'p1' => '**प्रोजेक्ट्स - सेटिंग्ज** मध्ये सात टॅब आहेत, आणि प्रत्येकाला स्वतःची परवानगी लागते, जी **सिस्टम - भूमिका** वर दिली जाते; प्रोजेक्ट्स व्यवस्थापित करा सातही कव्हर करते. ज्याच्याकडे यापैकी एकही नाही त्याला कॉन्फिगर करण्यासारखे काही नाही असे सांगणारे पान दिसते.',
            'general_d' => 'तुम्ही दुसरी पद्धत निवडली नाही तर नवीन प्रोजेक्ट कसा चालवला जातो, प्रोजेक्ट्स कोण तयार करू शकते, कोण बदलू शकते, कोणत्या तारखा दिनदर्शिकेवर जातात आणि सेवा स्थितीवर व्यत्यय कसा जाहीर होतो. तसेच प्राधान्य शब्द, पोर्टफोलिओचा सुरुवातीचा क्रम, बर्न-अप काय मोजतो, बदल नियंत्रण (आपोआप बेसलाइन, कोण निर्णय घेते, स्वतःचा निर्णय, मंजुरीने काय होते), आढाव्यावरील टूलबॉक्स (चालू), AI असिस्टंटची स्मृती (प्रत्येकाची स्वतःची), कंत्राटदारांना ईमेल पाठवायचे का (बंद), मुदत संपलेल्या कार्यांचा डायजेस्ट (साप्ताहिक) आणि आठवणी (3 दिवसांनंतर), नवीन प्रोजेक्ट कोण पाहू शकते (प्रोजेक्ट्स असलेले सर्वजण), उघडी गेट चेकलिस्ट बाब गो थांबवते का (थांबवते), लाभांचे पुनरावलोकन किती वेळा होते (दर 3 महिन्यांनी) आणि कोणाला आठवण दिली जाते, आणि कोणत्या प्रस्तावांना मंजुरी लागते, कोण मंजूर करते आणि मंजुरीने काय होते.',
            'health_d' => 'चालू प्रोजेक्ट केव्हा पिवळा किंवा लाल होतो: लक्ष्य किती जवळ आहे, तोपर्यंत किती काम पूर्ण झाले पाहिजे, किती मुदत संपलेले काम त्याला लाल करते आणि किती नवीन जोडलेली तिकिटे त्याला पिवळा करतात; चुकलेला माइलस्टोन, किंवा तारखेनंतरचे अवलंबित्व किंवा निर्णय काय करतो (डीफॉल्टनुसार पिवळा); आणि क्षमता पानावरील आठवड्यातील तास, ताणलेली पातळी, अनेक प्रोजेक्ट्स, कामाचे दिवस आणि रोटा शिफ्ट मोजल्या जातात का.',
            'roles_d' => 'प्रोजेक्टच्या लोक टॅबवर दिल्या जाणाऱ्या भूमिका. क्रम बदलण्यासाठी ड्रॅग करा; भूमिका देणे थांबवण्यासाठी प्रोजेक्ट्सवर उपलब्ध टिक काढा; एक हटवल्याने तिचे धारक त्यांच्या प्रोजेक्ट्सवर भूमिकेशिवाय राहतात.',
            'raid_d' => 'संभाव्यता मापनाच्या आणि परिणाम मापनाच्या पायऱ्यांसाठी पाच शब्द, सर्वात कमी आधी.',
            'ai_d' => 'ब्रीफिंग आणि तयार केलेले अहवाल वापरत असलेला AI प्रदाता, मॉडेल आणि की. की तुमच्या संस्थेचा पैसा खर्च करते, म्हणून याला स्वतःची परवानगी आहे.',
            'budget_d' => 'नवीन प्रोजेक्ट्ससाठी चलन, प्रोजेक्ट स्वतःचे निवडू शकतो का, नोंदवलेल्या वेळाची किंमत कशी ठरते, आणि तासाचे दर - डीफॉल्ट आणि प्रत्येक विश्लेषकाचा - प्रत्येक एका तारखेपासून. तसेच अनुमत अतिरिक्त खर्च प्रत्यक्ष झालेला खर्च (डीफॉल्ट) मोजतो की अंदाज, आणि उघड्या कार्यांवर अजून अंदाजित तास अंदाजात मोजले जातात का (मोजले जातात).',
            'templates_d' => 'नवीन प्रोजेक्ट्ससाठी दिले जाणारे टेम्पलेट: अंगभूत टेम्पलेट लपवा, आणि प्रोजेक्टमधून जतन केलेल्यांचे नाव बदला, ते बंद करा किंवा हटवा. हीच परवानगी एखाद्याला प्रोजेक्ट टेम्पलेट म्हणून जतन करू देते.',
            'p2' => '**प्रोजेक्ट्स कोण तयार करू शकते** यात प्रोजेक्ट्स उघडू शकणारे कोणीही (डीफॉल्ट) किंवा फक्त प्रोजेक्ट्स व्यवस्थापित करणारे लोक असतात. **प्रोजेक्ट कोण बदलू शकते** यात त्याचा संघ (डीफॉल्ट) किंवा प्रोजेक्ट्स उघडू शकणारे कोणीही असते. प्रोजेक्टचा संघ म्हणजे त्याचा प्रोजेक्ट मॅनेजर, तो तयार करणारी व्यक्ती आणि त्याचे सदस्य, सदस्य असलेल्या संघातील विश्लेषकांसह. प्रोजेक्ट्स व्यवस्थापित करणारे लोक आणि प्रशासक कोणताही प्रोजेक्ट नेहमी बदलू शकतात.',
            'p3' => 'प्रोजेक्ट **हटवणे** सेटिंग्ज काहीही म्हणत असल्या तरी नेहमी त्याचा प्रोजेक्ट मॅनेजर, तो तयार करणारी व्यक्ती आणि प्रोजेक्ट्स व्यवस्थापित करणारे लोक यांच्यापुरते मर्यादित असते. तुम्हाला प्रोजेक्ट बदलण्याची परवानगी नसताना, त्याचे पान बदल करणारी बटणे लपवते, आणि सर्व्हर तरीही बदल नाकारतो.',
        ],
        'api' => [
            'nav' => 'API',
            'title' => 'API द्वारे प्रोजेक्ट्स',
            'intro' => 'स्क्रिप्ट्स, इतर सिस्टम्स आणि AI असिस्टंट्ससाठी.',
            'p1' => 'प्रोजेक्ट्स REST API द्वारे वाचता आणि बदलता येतात, आणि MCP सर्व्हरद्वारे AI असिस्टंट वाचू शकतो. दोन्ही **सिस्टम - API** मध्ये सेट केले जातात, आणि API की फक्त तिच्या विश्लेषकाला दिसणाऱ्या कंपन्यांपर्यंतच पोहोचते.',
            'p2' => '**War Room** मध्ये, Warbot प्रोजेक्ट्सबद्दलचे प्रश्नही उत्तरतो - "कोणते प्रोजेक्ट्स मार्गावर नाहीत?", "या आठवड्यात कोणता प्रोजेक्ट काही मोठे करत आहे का?" - किंवा **/projects**, **/project** आणि **/dates** वापरा. तो फक्त प्रोजेक्ट्स उघडू शकणाऱ्या लोकांना दिला जातो, त्यांना दिसणाऱ्या प्रोजेक्ट्सबद्दल उत्तर देतो, आणि पैशाचा उल्लेख कधीही करत नाही: चॅनेलमधील प्रत्येकजण त्याची उत्तरे वाचतो.',
        ],
    ],
